    /// GEN-3 (fallback rule): a completion with no final text renders what the ledger capture
    /// PROVES it did — the files it wrote and its last pytest outcome — and when the capture
    /// holds neither fact it renders nothing (the dispatcher then hands dependents an honest
    /// empty and emits `dependency_context_empty`). The "(task X completed)" stub can never
    /// reach a dependent's "relevant context" again.
    #[test]
    fn an_empty_completion_says_what_it_wrote_or_nothing_at_all() {
        let dir = r2_cut_ledger_fixture();
        let facts = render_completed_output_from_ledger(
            dir.path(),
            "ledger-core-tests",
            &["tests/test_ledger_core.py".to_string()],
            0,
            None,
        )
        .expect("a capture with fs_delta and pytest rows renders facts");
        assert!(
            facts.contains("wrote: tests/test_ledger_core.py"),
            "the fs_delta is the wrote-line:\n{facts}"
        );
        assert!(
            facts.contains("1 failed, 0 passed"),
            "the LAST pytest outcome is the fact carried:\n{facts}"
        );
        assert!(
            !facts.contains("completed)"),
            "the stub phrasing is gone:\n{facts}"
        );
        let bare = tempfile::tempdir().unwrap();
        assert!(
            render_completed_output_from_ledger(bare.path(), "ghost", &[], 0, None).is_none(),
            "no capture, no facts — an honest None, never a stub"
        );
    }

    /// GEN-6a #3 (fallback rule): a ledger mini that fails to parse must not be silently
    /// dropped — the roll-up names it in `rows_dropped`, the read-before-act block SAYS the
    /// table is incomplete, and an intact ledger's roll-up bytes are unchanged.
    #[test]
    fn a_corrupt_ledger_mini_is_named_never_silently_dropped() {
        let dir = r2_cut_ledger_fixture();
        let root = dir.path();
        let clean = read_ledger_rollup(root).expect("fixture roll-up exists");
        assert!(
            clean.get("rows_dropped").is_none(),
            "an intact ledger carries no rows_dropped field at all"
        );
        std::fs::write(root.join(".swarm/ledger/corrupt-row.json"), "{not json").unwrap();
        let rollup = rebuild_ledger_rollup(root).expect("rebuild still succeeds");
        let dropped = rollup["rows_dropped"]
            .as_array()
            .expect("the dropped row is named");
        assert_eq!(dropped.len(), 1);
        assert_eq!(dropped[0]["file"], "corrupt-row.json");
        assert!(
            dropped[0]["error"].as_str().unwrap().contains("key"),
            "the parse error travels with the file name: {:?}",
            dropped[0]["error"]
        );
        let block = render_ledger_block(root, "integrate-verify", &[], &[], 7_000, None);
        assert!(
            block.contains("UNREADABLE") && block.contains("corrupt-row.json"),
            "the reader is TOLD the table is incomplete:\n{block}"
        );
    }

    /// GEN-6a #5/#6: a package.json that EXISTS but does not parse is a broken file, not an
    /// absent one — the TS smoke gate reports inconclusive-with-reason instead of a clean skip.
    #[tokio::test]
    async fn a_malformed_package_json_is_inconclusive_not_a_clean_skip() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("package.json"), "{\"name\": ").unwrap();
        let r = smoke_typescript(dir.path()).await;
        assert!(!r.ran && r.findings.is_empty(), "never a finding");
        assert!(
            r.inconclusive
                .iter()
                .any(|i| i.contains("package.json exists but does not parse")),
            "the reason is stated: {:?}",
            r.inconclusive
        );
        // No package.json at all stays an honest, reasonless skip — the gate does not apply.
        let bare = tempfile::tempdir().unwrap();
        let skipped = smoke_typescript(bare.path()).await;
        assert!(!skipped.ran && skipped.inconclusive.is_empty());
    }

    /// II-2b: the read-before-act block renders the facts the r2 sink re-derived by hand — the
    /// test table with each lane's last outcome, the don't-repeat run counts, the out-of-plan
    /// testgen files with their unowned imports, and the repair verdict nothing used to read.
    #[test]
    fn render_ledger_block_carries_the_facts_the_r2_sink_rederived() {
        let dir = r2_cut_ledger_fixture();
        let block = render_ledger_block(
            dir.path(),
            "integrate-verify",
            &["ledger-core-tests".to_string()],
            &[],
            7_000,
            Some("ImportError: cannot import name 'approve' from 'app.approval_workflow'"),
        );
        assert!(
            block.chars().count() <= 7_000,
            "budget held: {}",
            block.len()
        );
        assert!(
            block.contains("tests/test_ledger_core.py + tests/test_ledger_concurrency.py")
                && block.contains("7 failed, 19 passed"),
            "test table names the lane's files and last outcome:\n{block}"
        );
        assert!(
            block.contains("pytest already ran 4 time(s) across 3 lane(s)"),
            "the §II.3 don't-repeat fact counts every lane's runs:\n{block}"
        );
        assert!(
            block.contains("Last full run: 43 passed"),
            "the whole-suite outcome is separated from targeted re-runs:\n{block}"
        );
        assert!(
            block.contains("test_interfaces.py (written during `integrate-verify`)"),
            "the out-of-plan testgen file is attributed:\n{block}"
        );
        assert!(
            block.contains("imports `app.approval_workflow`"),
            "the unowned task-id import is an open defect:\n{block}"
        );
        assert!(
            block.contains("FINDING 1 NOT FIXED")
                && block.contains("registered the route on the wrong handler class"),
            "the repair verdict nothing used to parse is now read back:\n{block}"
        );
        assert!(
            block.contains("`pytest --collect-only` has ALREADY been run"),
            "the engine-run collect-only arrives as input:\n{block}"
        );
        // Deps-first ordering: the named dependency's row renders before the stranger lane's.
        let dep = block.find("ledger-core-tests").unwrap();
        let stranger = block.find("vendor-sync-edge-tests").unwrap();
        assert!(dep < stranger, "dependency rows render first");
    }

    /// II-3 acceptance, on the REAL sb-7 spec and the r2 archive's shapes: the sink's dispatch
    /// is a semantic description carrying the facts the live r2 sink re-derived by hand — the
    /// approval module's real exports, the root tests' task-id imports, the suite's run count —
    /// and the zero-fact template line is GONE from it.
    #[test]
    fn sink_semantic_description_replaces_the_template_with_r2s_facts() {
        let dir = r2_cut_ledger_fixture();
        let root = dir.path();
        // The approval module's real surface, cut from the r2 archive's app/drafts.py.
        std::fs::write(
            root.join("app/drafts.py"),
            "def approve_draft(db, draft_id: str, approved_by: str) -> dict:\n    return {}\n\n\
             def reject_draft(db, draft_id: str, rejected_by: str) -> dict:\n    return {}\n\n\
             def create_draft(db, amount_minor: int, currency: str) -> dict:\n    return {}\n",
        )
        .unwrap();
        std::fs::write(
            root.join("app/stream.py"),
            "def sse_handler(request):\n    return None\n",
        )
        .unwrap();
        let spec = include_str!("../../../../evals/swarm-bench/spec-build-sb7.md");
        // The r2 plan's declared manifest (task_owns union from the archived run.jsonl).
        let all_files: Vec<String> = [
            "app/auth.py",
            "app/drafts.py",
            "app/ledger_core.py",
            "app/api.py",
            "app/stream.py",
            "app/vendor_sync.py",
            "app/webhook.py",
            "app/cli.py",
            "app/__main__.py",
            "app/ledgerd/__main__.py",
            "app/notifierd/__main__.py",
            "tests/test_ledger_core.py",
            "tests/test_ledger_concurrency.py",
            "tests/test_vendor_sync_edge.py",
            "tests/test_sync_resilience.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let brief = sink_semantic_description(
            root,
            "integrate-verify",
            &[],
            &all_files,
            spec,
            TargetLang::Python,
            Some("ImportError: cannot import name 'approve' from 'app.approval_workflow'"),
            budgets::LEDGER_BLOCK_CHARS,
        );
        assert!(
            !brief.ledger_empty && !brief.spec_surface_empty,
            "a populated ledger and a real spec surface report no absences"
        );
        let desc = brief.description;
        assert!(
            !desc.contains("Integrate every module and VERIFY"),
            "the zero-fact template line must be gone"
        );
        assert!(
            desc.contains("app/drafts.py: approve_draft"),
            "drafts.py is named the approval module by its own exports:\n{desc}"
        );
        assert!(
            desc.contains("imports `app.approval_workflow`"),
            "the root tests' task-id import is carried as a defect:\n{desc}"
        );
        assert!(
            desc.contains("pytest already ran 4 time(s) across 3 lane(s)"),
            "the suite's run count arrives as input, not as a blocked tool:\n{desc}"
        );
        assert!(
            desc.contains("--ledger-port") && desc.contains("BOOT exactly"),
            "the literal boot argv shape is quoted from the spec:\n{desc}"
        );
        assert!(
            desc.contains("GET /api/payments") && desc.contains("POST /api/sync"),
            "the advertised endpoints come from the gate's own parsers:\n{desc}"
        );
        assert!(
            desc.contains("do NOT write re-export shims"),
            "the r2 phantom-shim class is named at the moment it would recur"
        );
        assert!(
            !desc.contains("READS a PERSISTED file"),
            "the CLI/JSON-store paragraph drops when the spec advertises endpoints"
        );
        // GEN-1 arming rule: an empty ledger no longer forfeits the semantic build — the spec
        // facts still arm it, the ledger's absence is STATED, and the flag the caller turns
        // into `ledger_empty_at_sink` is set. The template never comes back.
        let bare = tempfile::tempdir().unwrap();
        let empty_ledger = sink_semantic_description(
            bare.path(),
            "integrate-verify",
            &[],
            &all_files,
            spec,
            TargetLang::Python,
            None,
            budgets::LEDGER_BLOCK_CHARS,
        );
        assert!(
            empty_ledger.ledger_empty && !empty_ledger.spec_surface_empty,
            "the absence is a named flag, and a real spec keeps the surface non-empty"
        );
        assert!(
            !empty_ledger
                .description
                .contains("Integrate every module and VERIFY"),
            "an empty ledger must arm the spec-fact brief, never the banned template"
        );
        assert!(
            empty_ledger.description.contains("LEDGER: EMPTY")
                && empty_ledger.description.contains("BOOT exactly"),
            "the brief states the ledger's absence while still carrying the spec's boot facts:\n{}",
            empty_ledger.description
        );
    }

    /// GEN-1's reachability gate, in the style of `no_prompt_reintroduces_the_frozen_interfaces_section`:
    /// the banned "Integrate every module and VERIFY…" constant must be UNREACHABLE as a dispatched
    /// description. Functional half: with NOTHING — no ledger, no spec, no tree — the sink brief is
    /// still built and states its measured absences. Source half: the builder's signature must stay
    /// non-Option, because `-> Option<String>` WAS the mechanism that re-dispatched the template on
    /// every empty-ledger sink (the caller's `unwrap_or(&req.description)` is the only join).
    #[test]
    fn the_banned_integrate_template_cannot_reach_a_dispatch() {
        let bare = tempfile::tempdir().unwrap();
        let brief = sink_semantic_description(
            bare.path(),
            "integrate-verify",
            &[],
            &[],
            "",
            TargetLang::Python,
            None,
            budgets::LEDGER_BLOCK_CHARS,
        );
        assert!(
            brief.ledger_empty && brief.spec_surface_empty,
            "both absences are measured, not defaulted"
        );
        assert!(
            !brief
                .description
                .contains("Integrate every module and VERIFY"),
            "even a fully empty world must never re-arm the template"
        );
        assert!(
            brief.description.contains("MEASURED ABSENCE")
                && brief.description.contains("LEDGER: EMPTY"),
            "the empty-world brief states both absences instead of substituting:\n{}",
            brief.description
        );
        let src = include_str!("swarm.rs");
        // Built by concat so this test's own source can never satisfy its own search.
        let needle = ["fn sink_semantic_", "description("].concat();
        let decl: String = src
            .split(&needle)
            .nth(1)
            .expect("the sink brief builder exists")
            .chars()
            .take_while(|c| *c != '{')
            .collect();
        // Only the RETURN type — a parameter may legitimately be an Option (collect_only is).
        let ret = decl
            .rsplit("->")
            .next()
            .expect("the builder returns a value");
        assert!(
            !ret.contains("Option<"),
            "the sink brief builder must return unconditionally — an Option here is the exact \
             empty-input fallback that shipped the banned template (GEN-1)"
        );
    }

    /// II-11c (engine half): the forming fold's full lifecycle — an open frame renders name +
    /// since + args_bytes:0 with NO args_preview (an empty preview would impersonate content),
    /// ArgsDelta fragments advance the byte count and surface a preview, Complete removes the
    /// row, and an empty map means the file is REMOVED, never written empty (an empty forming
    /// file would read as a live amber row in the panel join).
    #[test]
    fn a_forming_open_frame_renders_and_its_completion_clears() {
        use goose_provider_types::formats::openai::ToolFormingEvent;
        let mut live = std::collections::BTreeMap::new();
        fold_forming_event(
            &mut live,
            ToolFormingEvent::Forming {
                id: "call_1".into(),
                name: "write_file".into(),
                since: std::time::Instant::now(),
            },
        );
        fold_forming_event(
            &mut live,
            ToolFormingEvent::Forming {
                id: "call_2".into(),
                name: "shell".into(),
                since: std::time::Instant::now(),
            },
        );
        let body = render_forming_file(&live).expect("two forming rows render");
        assert!(body.contains("write_file") && body.contains("shell") && body.contains("since_ms"));
        assert!(
            body.contains("\"args_bytes\":0") && !body.contains("args_preview"),
            "no fragments yet: bytes honestly 0, preview OMITTED, got {body}"
        );
        fold_forming_event(
            &mut live,
            ToolFormingEvent::ArgsDelta {
                id: "call_1".into(),
                delta: "{\"path\": \"a.py\", \"content\": \"x\"}".into(),
            },
        );
        let body = render_forming_file(&live).unwrap();
        assert!(
            body.contains("\"args_bytes\":32") && body.contains("args_preview"),
            "fragments arrived: bytes counted and a preview rendered, got {body}"
        );
        fold_forming_event(
            &mut live,
            ToolFormingEvent::Complete {
                id: "call_1".into(),
            },
        );
        let body = render_forming_file(&live).unwrap();
        assert!(!body.contains("write_file") && body.contains("shell"));
        fold_forming_event(
            &mut live,
            ToolFormingEvent::Complete {
                id: "call_2".into(),
            },
        );
        assert!(
            render_forming_file(&live).is_none(),
            "empty means REMOVE the file, never write it empty"
        );
    }

    /// II-11c: the tail is trimmed on CHAR boundaries (a delta may split multi-byte UTF-8
    /// anywhere), and the preview window is bounded and front-trimmed without ever splitting a
    /// character.
    #[test]
    fn forming_tail_truncation_is_utf8_boundary_safe() {
        use goose_provider_types::formats::openai::ToolFormingEvent;
        let mut live = std::collections::BTreeMap::new();
        fold_forming_event(
            &mut live,
            ToolFormingEvent::Forming {
                id: "call_1".into(),
                name: "write_file".into(),
                since: std::time::Instant::now(),
            },
        );
        // 300 four-byte chars in two fragments: 1200 bytes, 300 chars — over the 240-char
        // preview window, under the 480-char tail, then a second wave pushes past 480 chars.
        for _ in 0..2 {
            fold_forming_event(
                &mut live,
                ToolFormingEvent::ArgsDelta {
                    id: "call_1".into(),
                    delta: "\u{1F600}".repeat(150),
                },
            );
        }
        fold_forming_event(
            &mut live,
            ToolFormingEvent::ArgsDelta {
                id: "call_1".into(),
                delta: "\u{1F600}".repeat(300),
            },
        );
        let row = live.get("call_1").expect("row lives");
        assert_eq!(
            row.args_bytes,
            600 * 4,
            "every byte counted, none displayed"
        );
        assert_eq!(
            row.args_tail.chars().count(),
            FORMING_TAIL_KEEP,
            "tail kept to the last {FORMING_TAIL_KEEP} CHARS on a boundary"
        );
        let preview = forming_preview(&row.args_tail);
        assert_eq!(
            preview.chars().count(),
            FORMING_PREVIEW_MAX,
            "no newline/sentence break in the window: the raw bounded window stands"
        );
    }

    /// II-11c: the preview opens just after the first newline (else the first sentence break)
    /// so the window does not start mid-token — unless that trim would empty it, in which case
    /// the raw window IS the content.
    #[test]
    fn forming_preview_trims_to_a_readable_front() {
        let with_newline = format!("{}\nsecond line tail", "x".repeat(300));
        assert_eq!(forming_preview(&with_newline), "second line tail");
        let with_sentence = "A first sentence. then the tail continues";
        assert_eq!(forming_preview(with_sentence), "then the tail continues");
        let trailing_newline = "all one line ending here\n";
        assert_eq!(
            forming_preview(trailing_newline),
            trailing_newline,
            "trimming to after the only newline would empty the preview: keep the raw window"
        );
        assert_eq!(forming_preview("short"), "short");
    }

    /// II-11c: an ArgsDelta whose open frame never arrived (impossible in today's decode order,
    /// possible after a decoder change) still counts honestly — the row is NAMED BY THE ID,
    /// never a fabricated tool name.
    #[test]
    fn an_orphan_args_delta_names_its_row_by_the_id() {
        use goose_provider_types::formats::openai::ToolFormingEvent;
        let mut live = std::collections::BTreeMap::new();
        fold_forming_event(
            &mut live,
            ToolFormingEvent::ArgsDelta {
                id: "call_orphan".into(),
                delta: "{\"k\":1}".into(),
            },
        );
        let row = live.get("call_orphan").expect("orphan delta still rows");
        assert_eq!(row.name, "call_orphan");
        assert_eq!(row.args_bytes, 7);
    }

    /// II-11c: the sidecar write is tmp+rename (main.ts's poll must never see a torn file — a
    /// torn read there is a one-poll row disappearance), and the drop guard clears BOTH the
    /// file and any stranded tmp — and a fix shard's real-tree MIRROR with them: a stale
    /// mirrored forming.json would read as a live amber row in the panel join forever.
    #[test]
    fn forming_write_is_atomic_and_the_guard_clears_both_files() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("open.forming.json");
        let mirror = dir.path().join("mirrored.forming.json");
        write_forming_atomic(&path, "{\"forming\":[]}").expect("atomic write");
        assert!(path.is_file());
        assert!(
            !forming_tmp(&path).exists(),
            "the rename consumed the tmp — never left behind"
        );
        std::fs::write(forming_tmp(&path), "torn").expect("strand a tmp");
        write_forming_atomic(&mirror, "{\"forming\":[]}").expect("mirror write");
        drop(FormingGuard {
            path: path.clone(),
            mirror: Some(mirror.clone()),
            report: None,
        });
        assert!(!path.exists(), "guard removed the sidecar");
        assert!(!forming_tmp(&path).exists(), "guard removed the tmp too");
        assert!(!mirror.exists(), "guard removed the real-tree mirror too");
    }

    /// HANDOFF-1: the handoff instruction is ONE constant riding the ONE shared rules join —
    /// appended inside each kind's branch it would drift into N disagreeing copies (the defect
    /// class this repo keeps refinding). Grep-style, like the frozen-interfaces gate.
    #[test]
    fn every_worker_kind_carries_the_handoff_rule() {
        let src = include_str!("swarm.rs");
        // Built by concat so this test's own source cannot satisfy the search.
        let needle = ["{stopping_rules}", "{HANDOFF_RULE}"].concat();
        assert!(
            src.contains(&needle),
            "HANDOFF_RULE must ride the shared reading/stopping rules join, not per-kind copies"
        );
        assert!(
            HANDOFF_RULE.contains("exact")
                && HANDOFF_RULE.contains("next step")
                && HANDOFF_RULE.contains("Do NOT restate the spec"),
            "the constant carries the three load-bearing clauses"
        );
    }

    /// II-4: a round-0 NOT FIXED verdict reaches the round-1 shard's text VERBATIM — the fresh
    /// per-round Scheduler discards its SharedContext, so the on-disk repair ledger is the only
    /// channel between rounds, and this is the splice that reads it.
    #[test]
    fn a_round0_not_fixed_verdict_reaches_the_round1_shard_text() {
        let dir = r2_cut_ledger_fixture();
        let rollup = read_ledger_rollup(dir.path());
        let findings = vec!["GET /api/stream returned 404 (advertised SSE endpoint)".to_string()];
        let history = render_repair_history(
            rollup.as_ref(),
            &["app/stream.py".to_string()],
            &findings,
            1,
            ledger_block::REPAIR_HISTORY_CHARS,
        );
        assert!(history.chars().count() <= 3_500, "one dep-file budget");
        assert!(
            history.contains(
                "round 0, fix::r0::app/stream.py: FINDING 1 NOT FIXED — registered the route \
                 on the wrong handler class"
            ),
            "the prior verdict arrives verbatim:\n{history}"
        );
        assert!(
            history.contains("GATE round 0"),
            "the round's gate row frames the findings:\n{history}"
        );
        let desc = smoke_fix_description(&findings, TargetLang::Python, "", &history);
        assert!(
            desc.contains("FINDING 1 NOT FIXED — registered the route on the wrong handler class"),
            "findings and prior attempts arrive in ONE message"
        );
        assert_eq!(
            parse_numbered_findings(&desc),
            findings,
            "the history block must not corrupt the numbered-findings recovery"
        );
        // The owning tasks' rows arrive when the shard's files overlap a builder's.
        let owner_history = render_repair_history(
            rollup.as_ref(),
            &["tests/test_ledger_core.py".to_string()],
            &[],
            1,
            ledger_block::REPAIR_HISTORY_CHARS,
        );
        assert!(
            owner_history.contains("`ledger-core-tests` built these files"),
            "the shard learns who built what it repairs:\n{owner_history}"
        );
        // This round's own verdicts are not "prior" — round 0 must not read round 0 back.
        let same_round = render_repair_history(
            rollup.as_ref(),
            &["app/stream.py".to_string()],
            &findings,
            0,
            ledger_block::REPAIR_HISTORY_CHARS,
        );
        assert!(!same_round.contains("NOT FIXED"));
        // No ledger, no history — and an empty history keeps the description byte-identical.
        assert_eq!(
            render_repair_history(None, &[], &findings, 1, ledger_block::REPAIR_HISTORY_CHARS),
            ""
        );
        assert_eq!(
            smoke_fix_description(&findings, TargetLang::Python, "", ""),
            smoke_fix_description(&findings, TargetLang::Python, "", " \n "),
        );
    }

    /// II-2b: an absent or unreadable ledger renders EMPTY — the dispatch proceeds
    /// byte-identical, which is the never-gates rule in executable form.
    #[test]
    fn render_ledger_block_is_empty_without_a_ledger() {
        let dir = tempfile::tempdir().unwrap();
        assert_eq!(
            render_ledger_block(dir.path(), "t", &[], &[], 7_000, None),
            ""
        );
        std::fs::create_dir_all(dir.path().join(".swarm")).unwrap();
        std::fs::write(dir.path().join(".swarm/ledger.json"), "not json{{{").unwrap();
        assert_eq!(
            render_ledger_block(dir.path(), "t", &[], &[], 7_000, None),
            ""
        );
    }

    /// II-2b: over budget, the droppables go first (ok-only command classes, then lane
    /// self-reports) and NEVER a defect, a gate finding, or a NOT FIXED verdict; the last
    /// resort is a line-boundary cut that says it cut (F196 — a block stopping mid-line reads
    /// as a complete fact that is wrong).
    #[test]
    fn render_ledger_block_drop_order_never_drops_a_defect() {
        let dir = r2_cut_ledger_fixture();
        let full = render_ledger_block(dir.path(), "integrate-verify", &[], &[], 7_000, None);
        assert!(
            full.contains("ran clean"),
            "under budget the ok classes render"
        );
        assert!(
            full.contains("said:"),
            "under budget the self-reports render"
        );
        let squeezed = render_ledger_block(
            dir.path(),
            "integrate-verify",
            &[],
            &[],
            full.chars().count() - 1,
            None,
        );
        assert!(
            !squeezed.contains("ran clean"),
            "ok-only classes drop first"
        );
        assert!(
            squeezed.contains("NOT FIXED") && squeezed.contains("GET /api/stream returned 404"),
            "defects and verdicts survive the squeeze:\n{squeezed}"
        );
        let tiny = render_ledger_block(dir.path(), "integrate-verify", &[], &[], 700, None);
        assert!(tiny.chars().count() <= 700);
        assert!(
            tiny.contains("LEDGER TRUNCATED"),
            "a cut block says it was cut:\n{tiny}"
        );
        assert!(
            !tiny.trim_end().ends_with(','),
            "the cut lands on a line boundary"
        );
    }

    #[test]
    fn answers_win_floor_keeps_answered_plan_only_when_gated_and_non_structural() {
        use PostAnswerAction::*;
        // #129 nf-hexohm: gate ON, ask_replan the SOLE trigger, rescored 85 >= floor 85 -> keep (legacy shipped 52).
        assert_eq!(post_answer_action(true, true, false, 85, 85), KeepRescored);
        assert_eq!(post_answer_action(true, true, false, 86, 85), KeepRescored);
        // Gate ON, still below floor -> pin as the best_plan floor and re-draft to beat it.
        assert_eq!(
            post_answer_action(true, true, false, 52, 85),
            FloorAndRedraft
        );
        assert_eq!(
            post_answer_action(true, true, false, 84, 85),
            FloorAndRedraft
        );
        // Gate ON but STRUCTURAL -> never freeze a wrong-language/placeholder skeleton, even above the floor.
        assert_eq!(post_answer_action(true, true, true, 90, 85), Replan);
        assert_eq!(post_answer_action(true, false, true, 90, 85), Replan);
        // Gate ON, ask_replan off, non-structural -> unchanged reuse path.
        assert_eq!(post_answer_action(true, false, false, 40, 85), KeepReuse);
        // Gate OFF is byte-identical to legacy: (ask_replan || structural) => Replan, else KeepReuse.
        assert_eq!(post_answer_action(false, true, false, 85, 85), Replan);
        assert_eq!(post_answer_action(false, false, true, 90, 85), Replan);
        assert_eq!(post_answer_action(false, true, true, 90, 85), Replan);
        assert_eq!(post_answer_action(false, false, false, 40, 85), KeepReuse);
    }

    #[test]
    fn detail_memo_key_includes_goal_and_findings_not_just_id() {
        // A stable (id, brief, files) MUST NOT collide when goal or findings differ — that is the whole safety
        // argument: a user answering "argparse not click" appends to goal/findings and must FORCE a re-detail.
        let base = detail_memo_key("goal A", "cli", "build the cli", "cli.py", "findings X");
        // identical inputs -> identical key (a real hit)
        assert_eq!(
            base,
            detail_memo_key("goal A", "cli", "build the cli", "cli.py", "findings X")
        );
        // goal changed (e.g. USER_DECISIONS appended) -> DIFFERENT key -> re-details, not a stale reuse
        assert_ne!(
            base,
            detail_memo_key("goal B", "cli", "build the cli", "cli.py", "findings X")
        );
        // findings changed (re-research appended) -> DIFFERENT key
        assert_ne!(
            base,
            detail_memo_key("goal A", "cli", "build the cli", "cli.py", "findings Y")
        );
        // brief / id / files changes each flip the key too
        assert_ne!(
            base,
            detail_memo_key(
                "goal A",
                "cli",
                "build the CLI differently",
                "cli.py",
                "findings X"
            )
        );
        assert_ne!(
            base,
            detail_memo_key("goal A", "db", "build the cli", "cli.py", "findings X")
        );
        assert_ne!(
            base,
            detail_memo_key("goal A", "cli", "build the cli", "db.py", "findings X")
        );
        // The null separator prevents boundary collisions: ("ab","c") must not equal ("a","bc").
        assert_ne!(
            detail_memo_key("g", "ab", "c", "f", "x"),
            detail_memo_key("g", "a", "bc", "f", "x")
        );
    }

    #[test]
    fn backbone_round2_skips_only_when_lever_on_and_confidence_clears_floor() {
        // Lever OFF => byte-identical: round 2 runs whenever backbone is on, at any confidence.
        assert!(should_run_backbone_round2(true, false, 100));
        assert!(should_run_backbone_round2(true, false, 0));
        // Lever ON => skip (return false) only at/above the floor; below the floor the rescue re-draft still runs.
        assert!(!should_run_backbone_round2(
            true,
            true,
            BACKBONE_SKIP_CONF_FLOOR
        )); // 90 -> skip
        assert!(!should_run_backbone_round2(true, true, 100)); // verify-*/cov-poll case -> skip
        assert!(should_run_backbone_round2(
            true,
            true,
            BACKBONE_SKIP_CONF_FLOOR - 1
        )); // 89 -> still runs
        assert!(should_run_backbone_round2(true, true, 85)); // the lone historical adoption -> preserved
        assert!(should_run_backbone_round2(true, true, 53)); // shaky plan -> lock still available
                                                             // Backbone off => never runs regardless of the skip lever/confidence.
        assert!(!should_run_backbone_round2(false, false, 100));
        assert!(!should_run_backbone_round2(false, true, 50));
    }

    #[test]
    fn relax_contracted_deps_flattens_chain_keeps_sink_and_tests() {
        fn deps(plan: &serde_json::Value, id: &str) -> String {
            plan["subtasks"]
                .as_array()
                .unwrap()
                .iter()
                .find(|s| s["id"] == id)
                .unwrap()["depends_on"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|d| d.as_str())
                .collect::<Vec<_>>()
                .join(",")
        }
        // The measured nf-hexohm serial chain (core-types owns Cargo.toml) plus a per-module test that
        // genuinely runs against its module.
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core-types","depends_on":[],"files":["Cargo.toml","core/src/lib.rs","core/src/board.rs"]},
                {"id":"core-eval","depends_on":["core-types"],"files":["core/src/resistance.rs","core/src/eval.rs"]},
                {"id":"core-search","depends_on":["core-eval"],"files":["core/src/search.rs","core/src/solve.rs"]},
                {"id":"cli","depends_on":["core-search"],"files":["src/main.rs"]},
                {"id":"test-core-eval","depends_on":["core-eval"],"files":["core/src/eval_test.rs"]},
                {"id":"integrate-verify","depends_on":["core-types","core-eval","core-search","cli","test-core-eval"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = relax_contracted_module_deps(&mut plan, TargetLang::Rust);
        // every code module is now a root — the fleet can build all of them at once (no Cargo.toml ordering:
        // the per-worker gate no-ops without it and the sink owns the only real compile)
        assert_eq!(deps(&plan, "core-types"), "");
        assert_eq!(deps(&plan, "core-eval"), "");
        assert_eq!(deps(&plan, "core-search"), "");
        assert_eq!(deps(&plan, "cli"), "");
        // the per-module test is UNTOUCHED (signature-only contract cannot let it RUN against the module)
        assert_eq!(deps(&plan, "test-core-eval"), "core-eval");
        // the join still waits on everyone — compile/verify happens here, correctness preserved
        assert_eq!(
            deps(&plan, "integrate-verify"),
            "core-types,core-eval,core-search,cli,test-core-eval"
        );
        // dropped exactly: core-eval<-core-types, core-search<-core-eval, cli<-core-search
        assert_eq!(n, 3);
    }

    #[test]
    fn relax_contracted_deps_noop_on_flat_fan() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":[],"files":["b.py"]},
                {"id":"integrate-verify","depends_on":["a","b"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let before = plan.clone();
        let n = relax_contracted_module_deps(&mut plan, TargetLang::Python);
        assert_eq!(n, 0, "already a fan -> nothing to relax");
        assert_eq!(plan, before, "flat-fan plan left byte-identical");
    }

    // ---- SINK DECOMPOSITION (fan-verify) ---------------------------------------------------
    fn fv_deps(plan: &serde_json::Value, id: &str) -> String {
        plan["subtasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["id"] == id)
            .unwrap()["depends_on"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|d| d.as_str())
            .collect::<Vec<_>>()
            .join(",")
    }
    fn fv_task<'a>(plan: &'a serde_json::Value, id: &str) -> Option<&'a serde_json::Value> {
        plan["subtasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["id"] == id)
    }

    #[test]
    fn fan_verify_split_skips_docs_only_modules() {
        // A `readme` module owning only markdown got a verify:: gate whose spec is
        // import/build-check language — a 27B dispatched to import-check MARKDOWN (operator
        // report). Docs-only modules have no isolated surface; mixed modules still fan.
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"readme","depends_on":["core"],"files":["README.md"]},
                {"id":"docs","depends_on":["core"],"files":["docs/guide.md","LICENSE"]},
                {"id":"web","depends_on":["core"],"files":["web/index.html","web/README.md"]},
                {"id":"integrate-verify","depends_on":["core","readme","docs","web"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = fan_verify_split(&mut plan, TargetLang::Python);
        assert_eq!(n, 2, "core and web fan; readme and docs do not");
        assert!(fv_task(&plan, "verify::core").is_some());
        assert!(
            fv_task(&plan, "verify::web").is_some(),
            "a module with ANY checkable file still gets its gate"
        );
        assert!(fv_task(&plan, "verify::readme").is_none());
        assert!(fv_task(&plan, "verify::docs").is_none());
    }

    #[test]
    fn fan_verify_split_emits_per_module_verify_and_thin_join() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"cli","depends_on":["core"],"files":["cli.py"]},
                {"id":"test-core","depends_on":["core"],"files":["test_core.py"]},
                {"id":"integrate-verify","depends_on":["core","cli","test-core"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = fan_verify_split(&mut plan, TargetLang::Python);
        assert_eq!(
            n, 2,
            "one verify task per file-owning non-test module (core, cli)"
        );
        // Each verify task depends on its module and NOTHING else — never on `test-core`, even though that
        // task writes core's tests. See a_verify_task_never_waits_on_a_test_subtask: that edge cascades a
        // failing test into integrate-verify and the end-to-end gate never runs.
        assert_eq!(fv_deps(&plan, "verify::core"), "core");
        assert_eq!(fv_deps(&plan, "verify::cli"), "cli");
        // No verify task issues ANY test command: the whole suite collects nothing this early and exits
        // CLEAN, which the model reads as a pass (MEASURED verify-6). Tests belong to `test-<module>`.
        for vid in ["verify::core", "verify::cli"] {
            let d = fv_task(&plan, vid).unwrap()["description"]
                .as_str()
                .unwrap()
                .to_string();
            assert!(d.contains("Run NO test command"), "{vid}");
            assert!(!d.contains("pytest"), "{vid} must get no pytest invocation");
        }
        for vid in ["verify::core", "verify::cli"] {
            assert!(
                fv_task(&plan, vid).unwrap()["files"]
                    .as_array()
                    .unwrap()
                    .is_empty(),
                "{vid} owns no files (read-only, fannable)"
            );
        }
        // No verify task for the test subtask.
        assert!(fv_task(&plan, "verify::test-core").is_none());
        // The thin join the split installs is the one the SINK ACTUALLY RECEIVES. The T2 canonicalizer in
        // parallel_plan re-writes integrate-verify's description ~200 lines later and used to hardcode the
        // FULL monolithic spec, so this thin text never reached a worker: every fan_verify run paid for N
        // extra verify tasks AND still ran the whole suite serially in the sink (36% of all node-busy time
        // across the corpus). T2 now selects thin_integrate_verify_spec when the split applied.
        assert_eq!(
            thin_integrate_verify_spec(TargetLang::Python),
            fv_task(&plan, "integrate-verify").unwrap()["description"]
                .as_str()
                .unwrap(),
            "the split's thin join must be exactly what T2 canonicalizes to"
        );
        // The join keeps its exact id, re-points module deps onto the verify tasks, and keeps the non-module
        // (test) dep. Order: mapped existing deps first, then any missing verify tasks appended (none here).
        assert_eq!(
            fv_deps(&plan, "integrate-verify"),
            "verify::core,verify::cli,test-core"
        );
        // The join is the thin whole-program oracle, not the monolithic suite-runner.
        let desc = fv_task(&plan, "integrate-verify").unwrap()["description"]
            .as_str()
            .unwrap();
        assert!(desc.contains("INTEGRATION JOIN"));
        assert!(desc.contains("SOLE integration gate"));
        assert!(
            !desc.contains("run the test suite"),
            "the whole-suite step moved to per-module verify"
        );
        // The module build tasks themselves are untouched.
        assert_eq!(fv_deps(&plan, "core"), "");
        assert_eq!(fv_deps(&plan, "cli"), "core");
    }

    /// A `verify::<M>` must NEVER depend on a test subtask — not even transitively, and not even to make a
    /// scoped test command safe to run.
    ///
    /// MEASURED (h1-treat-1): a version that added an edge onto whoever writes M's test file deadlocked the
    /// oracle. `test-wal` failed on a SyntaxError, `fail_descendants` cascaded Failed through `verify::wal`
    /// into `integrate-verify`, and the whole-program gate NEVER RAN. `strip_integrate_verify_test_deps`
    /// exists to keep a failing unit test from blocking the sink; routing the sink's dependency through a
    /// verify:: task re-introduces exactly that coupling.
    #[test]
    fn a_verify_task_never_waits_on_a_test_subtask() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"wal","depends_on":[],"files":["raftkv/wal.py"]},
                {"id":"test-wal","depends_on":["wal"],"files":["tests/test_wal.py"]},
                {"id":"integrate-verify","depends_on":["wal","test-wal"],"files":[]}
            ]}"#,
        )
        .unwrap();
        assert_eq!(fan_verify_split(&mut plan, TargetLang::Python), 1);
        // The ONLY edge is onto the module itself.
        assert_eq!(fv_deps(&plan, "verify::wal"), "wal");
        // And the verify spec issues NO test command, so there is nothing to be vacuous about: an empty or
        // not-yet-written suite can no longer exit CLEAN and read as a pass.
        let desc = fv_task(&plan, "verify::wal").unwrap()["description"]
            .as_str()
            .unwrap();
        assert!(desc.contains("Run NO test command"));
        assert!(!desc.contains("pytest"));
    }

    /// `id.contains("test")` classified any id with `test` ANYWHERE as a test subtask. A module called
    /// `latest-prices` therefore got NO `verify::` task and was ALSO left off the join's re-pointed dep
    /// list — verified by nothing, silently, while reading as a deliberate exclusion.
    #[test]
    fn a_module_whose_name_merely_contains_test_is_not_a_test_task() {
        // Real test ids stay tests (kebab and snake, any case).
        for id in [
            "tests",
            "test-core",
            "engine-tests",
            "tests-and-readme",
            "test_parser",
            "TESTS",
        ] {
            assert!(id_names_a_test(id), "{id} names a test");
        }
        // The false positives that cost a module its verify gate.
        for id in [
            "latest",
            "latest-prices",
            "contest",
            "attestation",
            "fastest-path",
            "testdata",
        ] {
            assert!(!id_names_a_test(id), "{id} is NOT a test task");
        }

        // End to end through the split: `latest-prices` now gets its verify task and the join gates on it.
        let mut plan = serde_json::json!({"subtasks":[
            {"id":"latest-prices","files":["latest.py"],"depends_on":[]},
            {"id":"integrate-verify","files":[],"depends_on":["latest-prices"]}
        ]});
        assert_eq!(fan_verify_split(&mut plan, TargetLang::Python), 1);
        assert!(fv_task(&plan, "verify::latest-prices").is_some());
        assert_eq!(fv_deps(&plan, "integrate-verify"), "verify::latest-prices");
    }

    #[test]
    fn fan_verify_split_is_idempotent_and_noops_without_sink() {
        // Idempotent: a second application does nothing (verify:: prefix already present).
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":[],"files":["b.py"]},
                {"id":"integrate-verify","depends_on":["a","b"],"files":[]}
            ]}"#,
        )
        .unwrap();
        assert_eq!(fan_verify_split(&mut plan, TargetLang::Python), 2);
        let after_first = plan.clone();
        assert_eq!(
            fan_verify_split(&mut plan, TargetLang::Python),
            0,
            "already fanned -> no-op"
        );
        assert_eq!(plan, after_first, "second application byte-identical");
        // No sink -> no-op, byte-identical.
        let mut no_sink: serde_json::Value =
            serde_json::from_str(r#"{"subtasks":[{"id":"a","depends_on":[],"files":["a.py"]}]}"#)
                .unwrap();
        let before = no_sink.clone();
        assert_eq!(fan_verify_split(&mut no_sink, TargetLang::Python), 0);
        assert_eq!(no_sink, before, "no sink -> plan left byte-identical");
    }

    // ---- TURN-CONTEXT STRIP -----------------------------------------------------------------
    /// The desktop prepends a per-turn `<turn-context>` block to the goal. MEASURED (loop-06): it is 171
    /// chars, and the retarget's research question uses `opts.prompt.chars().take(200)` — so the "task" the
    /// researcher was handed was 171 chars of XML and 28 chars of real spec. This fixture is the REAL wrapper
    /// copied from that run's run_started event, not a hand-made one.
    #[test]
    fn strip_turn_context_removes_the_real_desktop_wrapper() {
        let real = "<turn-context>\n<current-time>2026-07-16 14:52:00</current-time>\n\
                    <working-directory>/Users/mihaiperdum/goose-builds/loop-06-py-splitwise</working-directory>\n\
                    </turn-context>\nBuild \"Settle\" — a shared-expense splitter as a Python web app.";
        let out = strip_turn_context(real);
        assert!(
            out.starts_with("Build \"Settle\""),
            "the spec must lead, got: {:.60}",
            out
        );
        assert!(!out.contains("turn-context"));
        assert!(!out.contains("current-time"));
        // The first 200 chars a research question sees are now ALL spec.
        assert!(out
            .chars()
            .take(200)
            .collect::<String>()
            .contains("shared-expense splitter"));
    }

    #[test]
    fn strip_turn_context_leaves_everything_else_byte_identical() {
        // No wrapper -> untouched.
        let plain = "Build a Flask kanban app.";
        assert_eq!(strip_turn_context(plain), plain);
        // MENTIONS the words but is not the canonical wrapper -> untouched (never strip blindly).
        let mentions = "Write a parser for <turn-context> tags and a <current-time> helper.";
        assert_eq!(strip_turn_context(mentions), mentions);
        // Opens correctly but never closes -> untouched rather than eating the whole goal.
        let unclosed = "<turn-context>\n<current-time>2026</current-time>\nBuild an app.";
        assert_eq!(strip_turn_context(unclosed), unclosed);
        assert_eq!(strip_turn_context(""), "");
    }

    // ---- USER NOTES: run scoping + budget ----------------------------------------------------
    /// THE CROSS-RUN LEAK. Nothing ever cleared `.swarm/inbox`,
    /// so before the cutoff every note ever written to a project dir was injected into every worker of every
    /// FUTURE run there — under a header claiming it was "added while this build was running". Yesterday's
    /// "the DB is already seeded" silently steered today's fresh build.
    // ---- APP SCOPE: a static scan may only ever see the app THIS run built ------------------
    /// The manifest branch, the planned-directory sweep, and everything each must EXCLUDE. Reproduces the
    /// $HOME shape in miniature: unrelated trees beside the app, which the old os.walk(root) happily scanned
    /// (measured 10,916 .py under $HOME vs 8 in a build dir).
    #[test]
    fn app_scope_takes_the_manifest_and_planned_dirs_but_never_the_root_at_large() {
        let dir = std::env::temp_dir().join(format!("goose_scope_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("pkg")).unwrap();
        std::fs::create_dir_all(dir.join("Documents/other")).unwrap();
        std::fs::write(dir.join("pkg/a.py"), "x = 1\n").unwrap();
        // An UNPLANNED helper inside a planned dir IS the app's — that is what keeps the import graph closed.
        std::fs::write(dir.join("pkg/helper_unplanned.py"), "y = 2\n").unwrap();
        std::fs::write(dir.join("stray.py"), "z = 3\n").unwrap();
        std::fs::write(dir.join("Documents/other/x.py"), "w = 4\n").unwrap();

        // `main.py` is planned but NOT on disk (the pre-EXECUTE snapshot's greenfield case).
        let planned: Vec<String> = ["pkg/a.py", "main.py"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let scope = app_scope_py(&dir, &planned);
        let _ = std::fs::remove_dir_all(&dir);

        assert_eq!(
            scope.files,
            vec![
                "pkg/a.py".to_string(),
                "pkg/helper_unplanned.py".to_string()
            ],
            "the planned file + its planned dir, and NOTHING from the root or an unrelated tree"
        );
        assert!(scope.dropped.is_empty());
    }

    /// owned_files is MODEL-authored. One `..` or absolute entry would re-open the whole tree this closes.
    #[test]
    fn app_scope_refuses_an_escaping_manifest_entry() {
        let planned: Vec<String> = [
            "../../../etc/hosts.py",
            "/tmp/evil.py",
            "./pkg/a.py",
            "..\\..\\win.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        for d in scope_dirs(&planned) {
            assert!(
                d != ".." && !d.is_empty() && !d.starts_with('/'),
                "escaping dir: {d}"
            );
        }
        // The one legitimate entry is the only dir that survives.
        assert_eq!(scope_dirs(&planned), vec!["pkg".to_string()]);
    }

    /// A cap must produce a LABELLED PARTIAL, never a quiet short list — a silently-truncated scan reads
    /// as a clean tree, which is the false-green class this engine exists to prevent.
    #[test]
    fn app_scope_surfaces_dropped_files_instead_of_capping_silently() {
        let dir = std::env::temp_dir().join(format!("goose_scope_cap_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("pkg")).unwrap();
        let planned: Vec<String> = (0..5)
            .map(|i| {
                let rel = format!("pkg/m{i}.py");
                std::fs::write(dir.join(&rel), "x = 1\n").unwrap();
                rel
            })
            .collect();
        let scope = app_scope_py_capped(&dir, &planned, 2);
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(scope.files.len(), 2);
        assert_eq!(scope.dropped.len(), 3);
        assert_eq!(
            scope.files.len() + scope.dropped.len(),
            5,
            "nothing may VANISH — every file is either scanned or reported dropped"
        );
    }

    /// The teeth: `unwired_demotes_verified` defaults TRUE and can flip a run's `verified` to false off
    /// demote_survivors. A scan that did not see every file cannot prove a module is imported by nothing.
    #[test]
    fn a_partial_scan_can_never_demote() {
        let before = std::collections::HashSet::new();
        let complete = AstReviewResult {
            ran: true,
            modules: 3,
            findings: vec![],
            demote_eligible: vec!["kanban.db".to_string()],
            partial: false,
            parse_error: None,
        };
        assert_eq!(
            new_demote_survivors(&complete, &before),
            vec!["kanban.db".to_string()],
            "a COMPLETE scan may demote"
        );
        let partial = AstReviewResult {
            partial: true,
            ..complete.clone()
        };
        assert!(
            new_demote_survivors(&partial, &before).is_empty(),
            "a PARTIAL scan must never retract a green verdict"
        );
        let never_ran = AstReviewResult {
            ran: false,
            ..complete.clone()
        };
        assert!(new_demote_survivors(&never_ran, &before).is_empty());
    }

    // ---- APP ROOT GUARD ---------------------------------------------------------------------
    /// The desktop passes the session working directory, which with no project chosen is $HOME. A run
    /// treats its root as the app: it DELETES source files that appear under it (contracts cleanup),
    /// COPIES it whole (entry_help), and WALKS it (AST + drift scans). MEASURED at $HOME: 10,916 .py
    /// scanned vs 8 in a build dir, a 7-minute stall before any dispatch, and ~638 GB of attempted copy.
    #[test]
    fn home_and_its_ancestors_are_never_a_valid_app_root() {
        let home = Path::new("/Users/mihaiperdum");
        // The exact desktop default, and every ancestor of it.
        for bad in ["/Users/mihaiperdum", "/Users", "/"] {
            assert!(
                is_unsafe_app_root(Path::new(bad), home),
                "{bad} must never be treated as the app tree"
            );
        }
        // A real project dir — including the build dir we redirect INTO — stays untouched.
        for ok in [
            "/Users/mihaiperdum/goose-builds/swarm-20260727-190000000",
            "/Users/mihaiperdum/Projects/goose",
            "/tmp/scratch",
            "/Users/someone-else",
        ] {
            assert!(
                !is_unsafe_app_root(Path::new(ok), home),
                "{ok} is a legitimate project root and must be left alone"
            );
        }
    }

    /// The redirect target must itself be a SAFE root, or resolve_app_root would recurse into the same bug.
    #[test]
    fn the_redirect_target_is_itself_a_safe_root() {
        let home = Path::new("/Users/mihaiperdum");
        let target = home.join("goose-builds").join("swarm-20260727-190000000");
        assert!(!is_unsafe_app_root(&target, home));
    }

    // ---- ORPHAN / STUB FILE DETECTION -------------------------------------------------------
    #[test]
    fn orphan_source_files_flags_only_the_unplanned() {
        // loop-04's real case: dummy.swift shipped, in no task's owned_files.
        let on_disk = vec![
            "Sources/NotesLibrary/Note.swift".to_string(),
            "Sources/NotesLibrary/NoteStore.swift".to_string(),
            "Sources/NotesLibrary/dummy.swift".to_string(),
        ];
        let planned = vec![
            "Sources/NotesLibrary/Note.swift".to_string(),
            "Sources/NotesLibrary/NoteStore.swift".to_string(),
        ];
        assert_eq!(
            orphan_source_files(&on_disk, &planned),
            vec!["Sources/NotesLibrary/dummy.swift".to_string()]
        );
        // Separator + ./ normalization: a planned "./a.py" matches an on-disk "a.py".
        assert!(orphan_source_files(&["a.py".into()], &["./a.py".into()]).is_empty());
        // Nothing unplanned -> no orphans.
        assert!(orphan_source_files(&planned, &planned).is_empty());
    }

    #[test]
    fn is_stub_content_catches_placeholders_not_real_code() {
        assert!(is_stub_content("// NotesLibrary stub\nimport Foundation")); // the real dummy.swift
        assert!(is_stub_content("# placeholder"));
        assert!(is_stub_content("// TODO: implement\n"));
        assert!(is_stub_content("import Foundation")); // one meaningful line = trivial
        assert!(is_stub_content("")); // empty
                                      // Real code is not a stub.
        assert!(!is_stub_content(
            "func add(a: Int, b: Int) -> Int {\n return a + b\n}\nlet x = add(1, 2)"
        ));
    }

    // ---- RESEARCH PROVENANCE (grounded vs invented) -----------------------------------------
    /// A finding is GROUNDED only when the agent made a SUCCESSFUL EXTERNAL lookup — a research MCP call
    /// (web-search/context7). A failed call, no call, or a mere `developer__` shell command is not
    /// grounding: a pure guess (optionally dressed with a trivial `echo`) must never close a product decision.
    #[test]
    fn research_lookups_counts_only_successful_lookups() {
        let mk = |name: &str, is_mcp: bool, ok: Option<bool>| ToolCallRecord {
            name: name.to_string(),
            is_mcp,
            ok,
            fetched_external: false,
        };
        // A successful web-search / context7 call grounds it.
        let grounded = vec![
            mk("web-search__search", true, Some(true)),
            mk("context7__get-library-docs", true, Some(true)),
        ];
        assert_eq!(research_lookups(&grounded).len(), 2);

        // A shell command does NOT ground a product/convention decision — else a trivial `echo` before an
        // invented answer would launder the guess through the gate this exists to close.
        assert!(research_lookups(&[mk("developer__shell", false, Some(true))]).is_empty());
        assert!(research_lookups(&[mk("developer__text_editor", false, Some(true))]).is_empty());

        // NO tool calls -> pure reasoning -> NOT grounded (the laundering case).
        assert!(research_lookups(&[]).is_empty());

        // A FAILED lookup is not grounding — it looked nothing up.
        assert!(research_lookups(&[mk("web-search__search", true, Some(false))]).is_empty());
        // No response at all (max-turns cutoff) is not grounding.
        assert!(research_lookups(&[mk("context7__resolve-library-id", true, None)]).is_empty());
        // A shell BEFORE a real web-search still yields exactly the one EXTERNAL lookup.
        assert_eq!(
            research_lookups(&[
                mk("developer__shell", false, Some(true)),
                mk("web-search__search", true, Some(true)),
            ]),
            vec!["web-search__search".to_string()]
        );
    }

    /// P1 substrate: `classify_research_attempt` widens `grounded:bool` into the four cases the ASK-AWAY
    /// interim routing needs (CalledEmpty → ask the user; Errored/NeverCalled → retry the fetch). The
    /// CalledEmpty-vs-Errored boundary is the load-bearing distinction — verify it explicitly.
    #[test]
    fn classify_research_attempt_separates_the_four_cases() {
        let mk = |name: &str, is_mcp: bool, ok: Option<bool>| ToolCallRecord {
            name: name.to_string(),
            is_mcp,
            ok,
            fetched_external: false,
        };
        // NeverCalled: no tool call at all — pure model reasoning.
        assert_eq!(classify_research_attempt(&[]), ResearchAttempt::NeverCalled);
        // Grounded: at least one successful MCP lookup, and it wins even alongside a failed one.
        assert_eq!(
            classify_research_attempt(&[mk("web-search__search", true, Some(true))]),
            ResearchAttempt::Grounded
        );
        assert_eq!(
            classify_research_attempt(&[
                mk("web-search__search", true, Some(false)),
                mk("context7__get-library-docs", true, Some(true)),
            ]),
            ResearchAttempt::Grounded
        );
        // Errored: a lookup was attempted and failed or was cut off (Some(false) / None), none succeeded.
        assert_eq!(
            classify_research_attempt(&[mk("web-search__search", true, Some(false))]),
            ResearchAttempt::Errored
        );
        assert_eq!(
            classify_research_attempt(&[mk("context7__resolve-library-id", true, None)]),
            ResearchAttempt::Errored
        );
        // CalledEmpty: tools ran and none errored, but nothing grounded — only non-MCP shell calls.
        assert_eq!(
            classify_research_attempt(&[mk("developer__shell", false, Some(true))]),
            ResearchAttempt::CalledEmpty
        );
        // The field is populated on the struct — read it so the P1 substrate is exercised end to end.
        let f = ResearchFinding {
            question: "q".into(),
            kind: "web".into(),
            findings: "f".into(),
            grounded: false,
            lookups: Vec::new(),
            attempt: classify_research_attempt(&[mk("developer__shell", false, Some(true))]),
        };
        assert_eq!(f.attempt, ResearchAttempt::CalledEmpty);
    }

    // ---- PROVEN-CRASH DEMOTE ----------------------------------------------------------------
    // These replay the real archived runs in evals/swarm-gym/apps. The corpus contains exactly one
    // false-green and exactly one correctly-repaired app, and the rule must separate them.

    #[test]
    fn malformed_tool_name_recovers_the_quoted_name_without_panicking() {
        assert_eq!(
            malformed_tool_name(
                "The provided function name 'developer__shel' had invalid characters"
            ),
            "developer__shel (malformed)"
        );
        // No quoted name -> a marker, never an empty lane in the panel.
        assert_eq!(
            malformed_tool_name("arguments were not valid json"),
            "(malformed call)"
        );
        assert_eq!(malformed_tool_name("''"), "(malformed call)");
        // Multi-byte chars on the quote boundary must not panic (the message carries raw model output).
        assert_eq!(
            malformed_tool_name("bad name 'café—x' here"),
            "café—x (malformed)"
        );
        assert_eq!(malformed_tool_name("日本語のエラー"), "(malformed call)");
    }

    /// The demote path must read `demote_eligible`, not `findings` — the detector FLAGS standalone scripts
    /// (measured: this repo's own calls_report.py / conf_trail.py, both perfectly alive), so gating on the
    /// finding list would false-fail a correct app. Older stdout without the key must degrade to demoting
    /// nothing rather than to demoting everything.
    #[test]
    fn ast_review_demote_eligible_is_separate_from_findings() {
        let r = parse_ast_review(
            r#"{"modules":6,"findings":["module 'kanban.db' is imported by no non-test module — built-but-unwired (dead or unreachable from the app)"],"demote_eligible":["kanban.db"]}"#,
        );
        assert!(r.ran);
        assert_eq!(r.demote_eligible, vec!["kanban.db".to_string()]);

        // A flagged-but-alive script: a finding, but NOT demote-eligible.
        let scripts = parse_ast_review(
            r#"{"modules":2,"findings":["module 'calls_report' is imported by no non-test module — built-but-unwired (dead or unreachable from the app)"],"demote_eligible":[]}"#,
        );
        assert_eq!(
            scripts.findings.len(),
            1,
            "it must still be FLAGGED (advisory is free)"
        );
        assert!(
            scripts.demote_eligible.is_empty(),
            "a standalone script must never demote"
        );

        // Absent key (an older/other producer) -> demote nothing. Fail safe, never fail closed.
        let legacy = parse_ast_review(r#"{"modules":3,"findings":["x"]}"#);
        assert!(legacy.ran);
        assert!(legacy.demote_eligible.is_empty());

        // Unparseable -> ran=false, nothing to act on (a reviewer hiccup must not manufacture a demotion).
        let broken = parse_ast_review("not json");
        assert!(!broken.ran);
        assert!(broken.demote_eligible.is_empty());
        // GEN-6a #7: ran=false must carry WHY — a broken reviewer and a review that did not
        // apply were indistinguishable, and both read as a clean tree.
        assert!(
            broken
                .parse_error
                .as_deref()
                .is_some_and(|e| e.contains("not json")),
            "{:?}",
            broken.parse_error
        );
    }

    // ---- CONTEXTUAL PITFALL RETRIEVAL (the author finally gets the fact library) -------------------

    /// The HTTP-timeout fact must REACH the module that owns the client, and must not spray.
    ///
    /// `client_timeouts` is the only check of 35 where all four archived 3-node cells score below the
    /// 1-node cell — every one of them shipped "no request timeout". The fact existing in the library
    /// is worth nothing if no trigger carries it to the author, which is exactly the failure
    /// `pitfall_items_match_triggers` cannot see: that test only proves the ROW EXISTS.
    #[test]
    fn the_http_timeout_fact_reaches_a_client_task_and_no_one_else() {
        let client = relevant_pitfalls(
            "Build the Meridian client: fetch payments from http://127.0.0.1:8930/v1/payments",
        )
        .expect("a task that calls an HTTP endpoint must retrieve the timeout pitfall");
        assert!(client.contains("outbound HTTP call needs an EXPLICIT timeout"));

        // Library names, not domain words. The archived plans put "vendor" in 11 of 16 task specs and
        // "api" in 6, so triggering on either would hand this fact to tasks that open no socket.
        assert!(
            relevant_pitfalls("Store the vendor payment rows in the api schema").is_none(),
            "domain words must NOT trigger it — that is the crying-wolf this library forbids"
        );

        // And it must not drag the rest of the library along with it.
        assert!(
            !client.contains("CRON day-of-week"),
            "cron trivia must not ride along with the network fact"
        );
    }

    /// Every bool lever the golden bake ships ON must SAY so in its own doc block.
    ///
    /// The v1.41.94 bake flipped ~40 levers ON in `Default for SwarmConfig` and updated none of their
    /// prose, leaving 25 docs asserting "OFF by default" about behaviour that is now what ships (F392).
    /// That is not cosmetic: it made me publish a false claim about `sink_lean_prefill` — documented
    /// "None => OFF", actually `Some(true)` and ON in every archived run — and design an arm to enable
    /// something already enabled.
    ///
    /// The invariant is deliberately the SIMPLE one: presence of a marker, never "does the prose
    /// contradict the default". Phrase-matching was tried and failed three different ways (F393) — a
    /// claim split across two doc lines, a claim in `//` rather than `///`, and an off-by-default
    /// phrase sitting inside an ARGUMENT rather than an assertion. A marker has none of those shapes.
    /// A round that verified NOTHING must never read as a pass, however much else it recorded.
    ///
    /// MEASURED: 9 of 9 `spec_contract` events in the archive carried
    /// `verified: 0, findings: 0, inconclusive: 1` and the string "every advertised check that bound
    /// was satisfied". The old condition demanded all three counters be zero before saying "CHECKED
    /// NOTHING", so the single message explaining WHY it could not conclude promoted the round to
    /// success — the check reported best when it was most honest.
    #[test]
    fn a_spec_contract_round_that_verified_nothing_never_reads_as_a_pass() {
        // The exact archived shape: nothing bound, one recorded reason.
        assert!(
            spec_contract_detail(0, 0).starts_with("CHECKED NOTHING"),
            "{}",
            spec_contract_detail(0, 0)
        );
        // A real pass needs an affirmative 2xx, and only then.
        assert_eq!(
            spec_contract_detail(3, 0),
            "every advertised check that bound was satisfied"
        );
        // A finding outranks everything, including a verified endpoint alongside it.
        assert!(spec_contract_detail(0, 1).contains("blocking the green claim"));
        assert!(spec_contract_detail(3, 1).contains("blocking the green claim"));
        // The regression itself: verified==0 must NOT be rescued by a nonzero verified count elsewhere
        // or by any other signal — the only input that can produce a pass is `verified`.
        for verified in 0..4usize {
            let d = spec_contract_detail(verified, 0);
            assert_eq!(
                d == "every advertised check that bound was satisfied",
                verified > 0,
                "verified={verified} produced {d}"
            );
        }
    }

    /// VALIDATED AGAINST THE ARCHIVE BEFORE SHIPPING, in both directions: run over the five archived
    /// app trees, the script finds 0 findings in the one cell the scorer marks `client_timeouts` 1.00
    /// and 4/15/7/3 in the four it marks 0.00 — 5 of 5 agreement with an independent grader, including
    /// the production client (`vendorsync/meridian.py`) in two of them.
    ///
    /// This test covers the PARSER half, which is what runs without python.
    /// The advertised invocation is what makes the contract check able to conclude at all.
    #[test]
    fn spec_run_argv_v2_fills_each_placeholder_by_kind() {
        let tmp = tempfile::TempDir::new().unwrap();
        let spec = "Run `python -m vendorsync --db PATH --port N` to serve.";
        let (argv, ports) = spec_run_argv_v2(spec, "vendorsync", tmp.path(), 8999);
        assert_eq!(argv[0], "--db");
        assert!(argv[1].starts_with(&*tmp.path().to_string_lossy()));
        assert_eq!(argv[2], "--port");
        assert_eq!(ports.len(), 1);
        assert_eq!(argv[3], ports[0].to_string());

        // F910 defect 1, pinned: the sb-7 combined boot — TWO DISTINCT ports, a created
        // scratch dir, the spec's vendor base for URL, a scratch tokens file.
        let sb7 = "Boot: `python -m app --db-dir P --ledger-port N --notifier-port M --vendor URL --tokens-file T`";
        let (a, p2) = spec_run_argv_v2(sb7, "app", tmp.path(), 8901);
        assert_eq!(p2.len(), 2, "each port-flag gets its OWN port: {a:?}");
        assert_ne!(
            p2[0], p2[1],
            "the two services must never share a probe port"
        );
        let vendor = a[a.iter().position(|t| t == "--vendor").unwrap() + 1].clone();
        assert_eq!(
            vendor, "http://127.0.0.1:8901",
            "URL fills with the spec's vendor base"
        );
        let dbdir = a[a.iter().position(|t| t == "--db-dir").unwrap() + 1].clone();
        assert!(
            std::path::Path::new(&dbdir).is_dir(),
            "dir-flag gets a CREATED directory"
        );
        let tok = a[a.iter().position(|t| t == "--tokens-file").unwrap() + 1].clone();
        assert!(
            std::path::Path::new(&tok).is_file(),
            "token-flag gets a scratch file"
        );

        // Literals survive; no invocation / wrong package = empty.
        let (lit, _) = spec_run_argv_v2("`python -m app serve --port N`", "app", tmp.path(), 9);
        assert_eq!(lit[0], "serve");
        assert!(
            spec_run_argv_v2("Build a CLI. It should be fast.", "app", tmp.path(), 9)
                .0
                .is_empty()
        );
        assert!(
            spec_run_argv_v2("`python -m other --port N`", "app", tmp.path(), 9)
                .0
                .is_empty()
        );
    }

    #[test]
    fn spec_python_invocations_lists_every_advertised_entry_once() {
        let spec = "`python -m app --db-dir P` boots both. `python -m app.ledgerd --port N` alone. `python -m app.notifierd --port M` alone. Test with `python -m pytest`. Again: `python -m app --db-dir P`.";
        assert_eq!(
            spec_python_invocations(spec),
            vec!["app", "app.ledgerd", "app.notifierd"],
            "deduped, spec order, tool modules excluded"
        );
    }

    #[test]
    fn the_no_timeout_scan_turns_its_json_into_actionable_findings() {
        let d = parse_http_timeout(
            r#"{"checked": 3, "findings": [{"file": "vendorsync/meridian.py", "line": 55, "call": "urlopen"}]}"#,
        );
        assert!(d.ran);
        assert_eq!(d.checked, 3);
        assert_eq!(d.findings.len(), 1);
        assert!(d.findings[0].contains("vendorsync/meridian.py:55"));
        assert!(d.findings[0].contains("urlopen"));
        // The finding must forbid the cheap escapes, or a weak model deletes the call to clear it.
        assert!(d.findings[0].contains("Do not remove the call"));

        // A clean tree: ran, checked>0, no findings — distinguishable from "did not run".
        let clean = parse_http_timeout(r#"{"checked": 5, "findings": []}"#);
        assert!(clean.ran && clean.checked == 5 && clean.findings.is_empty());

        // Python is free to print a warning first; the last JSON line still wins.
        let noisy =
            parse_http_timeout("DeprecationWarning: whatever\n{\"checked\": 1, \"findings\": []}");
        assert!(noisy.ran && noisy.checked == 1);

        // Garbage must NOT read as a clean tree: `ran` stays false so `checked == 0` cannot be mistaken
        // for a scan that looked and found nothing (L230).
        let broken = parse_http_timeout("not json at all");
        assert!(
            !broken.ran,
            "unparseable output must not report a completed scan"
        );
    }

    /// REGRESSION, from a LIVE FALSE CLEAR — and the reason the test above was never enough.
    ///
    /// `the_no_timeout_scan_turns_its_json_into_actionable_findings` tests `parse_http_timeout`,
    /// which is the JSON PARSER. Nothing ever executed `HTTP_TIMEOUT_SCRIPT` itself, so the thing
    /// that actually decides what is a defect was the one part with no coverage. baseline-n1-r0
    /// then shipped `http.client.HTTPSConnection(self._host, self._port)` — timeout defaults to the
    /// global socket default of None, i.e. blocks FOREVER — and the scan emitted `findings: 0` twice
    /// while affirming every outbound call passed a timeout. A parser test cannot catch that.
    ///
    /// The negative controls matter as much as the positives: this scan feeds `verdict.findings`,
    /// which gates `final_passed`, so a false positive stops a CORRECT build and sends the repair
    /// loop to edit working code.
    #[tokio::test]
    async fn the_timeout_scan_sees_http_client_and_still_spares_a_positional_timeout() {
        let dir = std::env::temp_dir().join(format!("goose_http_to_{}", std::process::id()));
        let pkg = dir.join("pkg");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        // THE MEASURED DEFECT, in all three import forms it can wear.
        std::fs::write(
            pkg.join("bad.py"),
            "import http.client\nfrom http import client\nfrom http.client import HTTPSConnection\n\
             def a(h, p):\n    return http.client.HTTPSConnection(h, p)\n\
             def b(h):\n    return client.HTTPConnection(h)\n\
             def c(h):\n    return HTTPSConnection(h)\n",
        )
        .unwrap();
        // CORRECT CODE, which must stay silent: keyword timeout, and timeout in its POSITIONAL slot.
        std::fs::write(
            pkg.join("good.py"),
            "import http.client\nfrom urllib.request import urlopen\n\
             def a(h, p):\n    return http.client.HTTPSConnection(h, p, timeout=10)\n\
             def b(h, p):\n    return http.client.HTTPConnection(h, p, 30)\n\
             def c(u):\n    return urlopen(u, None, 30)\n",
        )
        .unwrap();
        let planned: Vec<String> = ["pkg/__init__.py", "pkg/bad.py", "pkg/good.py"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let res = http_timeout_scan(&dir, TargetLang::Python, &app_scope_py(&dir, &planned)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available in this environment
        }
        let joined = res.findings.join("\n");
        assert!(
            res.checked >= 2,
            "a scan that parsed nothing proves nothing (L230): checked={}",
            res.checked
        );
        for form in ["bad.py:5", "bad.py:7", "bad.py:9"] {
            assert!(
                joined.contains(form),
                "http.client with no timeout must be flagged at {form}: {joined}"
            );
        }
        assert!(
            !joined.contains("good.py"),
            "a timeout passed by keyword OR in its positional slot is CORRECT code and must not be \
             flagged — a false positive here sends the repair loop to break a working client: {joined}"
        );
    }

    /// F870 END-TO-END (L242: the DETECTOR, not the parser). The measured defect verbatim:
    /// swarm-3node-r0's styles.css defined 35 class rules and the markup wore almost none —
    /// the page shipped browser-default and every gate stayed green. The negative controls
    /// carry equal weight: this scan feeds `verdict.findings`, so a false fire sends the
    /// repair loop to break working styling. Review-hardened v2: the adversarial pass proved
    /// the first version's test PASSED VACUOUSLY (the gate resolved OFF and the early-return
    /// blamed python3), so this version checks python3 itself and then DEMANDS the scan ran.
    #[tokio::test]
    async fn css_coherence_flags_the_dead_stylesheet_and_spares_real_styling_shapes() {
        let have_py = std::process::Command::new("python3")
            .arg("--version")
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false);
        if !have_py {
            return; // the one legitimate skip; a dead gate can no longer hide behind it
        }
        let dir = std::env::temp_dir().join(format!("goose_cssco_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("web")).unwrap();
        // THE MEASURED DEFECT: id-only markup, a class-only stylesheet, js that builds rows
        // with literal classes from a THIRD vocabulary.
        std::fs::write(
            dir.join("web/index.html"),
            "<body><h1 id=\"title\">App</h1><table id=\"rows\"></table>\
             <div id=\"loading-state\">Loading</div></body>",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/styles.css"),
            "body { font-family: system-ui; } /* .ghost { color: red } */\n\
             .app-header { padding: 1rem } .btn { border: 0 } .btn-primary { background: #333 }\n\
             .toolbar { display: flex } .spinner { transition: .5s } .state-overlay { display: none }\n\
             .status-badge { background: url(ok.png) } .pagination { gap: 4px }\n\
             .summary-bar { color: #222 } .error-banner { color: red }\n\
             @media (max-width: 600px) { .table-wrapper { overflow-x: auto } }",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.js"),
            "document.getElementById('rows').innerHTML = '<tr><td class=\"cell-x\">x</td></tr>';",
        )
        .unwrap();
        let files: Vec<String> = ["web/index.html", "web/styles.css", "web/app.js"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let res = css_coherence_scan(&dir, &files).await;
        assert!(
            res.ran,
            "python3 is present yet the scan did not run — the gate is dead again (the exact \
             defect the review caught: swarm_gate(_, true) is not a default)"
        );
        assert_eq!(res.checked, 3, "all three web files must be parsed");
        assert_eq!(
            res.findings.len(),
            1,
            "an id-only page under a class-only stylesheet is THE unstyled-page defect: {:?}",
            res.findings
        );
        let f = &res.findings[0];
        for needle in [
            "web/styles.css",
            ".app-header",
            "defines 11 class rules",
            "do not delete the styling",
        ] {
            assert!(f.contains(needle), "finding must carry `{needle}`: {f}");
        }
        // The finding must lead with a SINGLE routable path token (multi-file "a.css, b.css"
        // prefixes fail is_code and fall to the unassigned bucket — review finding).
        let prefix = f.split(':').next().unwrap_or("");
        assert!(
            !prefix.contains(' ') && prefix.ends_with(".css"),
            "finding prefix must be one routable css path: {prefix}"
        );

        // COHERENT SHAPES, same scan — each must stay silent.
        // (a) literal classes wearing most of the stylesheet;
        std::fs::write(
            dir.join("web/index.html"),
            "<body class=\"app-header\"><button class=\"btn btn-primary\">Go</button>\
             <div class=\"toolbar spinner state-overlay summary-bar error-banner\"></div>\
             <span class=\"status-badge\"></span><nav class=\"pagination\"></nav></body>",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.js"),
            "el.classList.add('table-wrapper');\nrow.innerHTML = `<td class=\"status-badge\">ok</td>`;",
        )
        .unwrap();
        let clean = css_coherence_scan(&dir, &files).await;
        assert!(
            clean.ran && clean.findings.is_empty(),
            "a stylesheet the markup actually wears must stay silent: {:?}",
            clean.findings
        );
        // (b) the SPA shape from the review's fp1: classes applied via interpolated
        // attributes whose names live in constants/returns — the widened same-file literal
        // harvest must silence it.
        std::fs::write(
            dir.join("web/index.html"),
            "<body><div id=\"app\"></div></body>",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.js"),
            "const T = 'toolbar';\nfunction rowCls(r){ return r.ok ? 'app-header' : 'error-banner'; }\n\
             function badge(r){ if (r.s === 'paid') return 'btn btn-primary'; if (r.s === 'x') \
             return 'spinner state-overlay'; return 'status-badge pagination summary-bar table-wrapper'; }\n\
             app.innerHTML = `<div class=\"${T}\"><span class=\"${badge(r)} ${rowCls(r)}\"></span></div>`;",
        )
        .unwrap();
        let spa = css_coherence_scan(&dir, &files).await;
        let _ = std::fs::remove_dir_all(&dir);
        assert!(
            spa.ran && spa.findings.is_empty(),
            "computed-class SPAs whose names appear as literals must stay silent: {:?}",
            spa.findings
        );
    }

    /// F874: a task id with a path separator aimed its digest at a nonexistent directory and the
    /// write failed SILENTLY — every scheduled fix task ran invisible, and the judge, whose
    /// deterministic evidence IS that digest, was disarmed for exactly the tasks that repair the
    /// app (measured: 9 empty `ok` reviews in 10 minutes on one fix task). The key must be a flat
    /// filename AND must round-trip back to the task id, because the desktop indexes digests by
    /// filename and every consumer looks them up by task id.
    #[test]
    fn activity_digest_key_flattens_paths_and_round_trips() {
        // The desktop's decoder, mirrored here so the two can never drift apart: a left-to-right
        // scan of `~.` escape pairs (`~t` -> `~`, `~s` -> `/`, `~b` -> `\`).
        fn decode(k: &str) -> String {
            let mut out = String::new();
            let mut it = k.chars();
            while let Some(c) = it.next() {
                if c == '~' {
                    match it.next() {
                        Some('t') => out.push('~'),
                        Some('s') => out.push('/'),
                        Some('b') => out.push('\\'),
                        Some(other) => {
                            out.push('~');
                            out.push(other);
                        }
                        None => out.push('~'),
                    }
                } else {
                    out.push(c);
                }
            }
            out
        }
        for id in [
            "fix::r0::vendorsync/web/app.js",
            "fix::r12::a/b/c/d.py",
            "verify::web-index",
            "integrate-verify",
            "fix::r0::weird~name.py",
        ] {
            let k = activity_digest_key(id);
            assert!(
                !k.contains('/') && !k.contains('\\'),
                "digest key must be a flat filename: {k}"
            );
            assert_eq!(
                decode(&k),
                id,
                "the key must round-trip through the decoder"
            );
        }
        // INJECTIVE: a literal `~` and a separator must never collide on one digest file.
        // The escape alphabet's whole reason: adjacent mixes that the doubling scheme aliased.
        assert_ne!(
            activity_digest_key("fix::r0::a/~b"),
            activity_digest_key("fix::r0::a~/b"),
            "adjacent mixed separators must not alias"
        );
        assert_ne!(
            activity_digest_key("fix::r0::a/b"),
            activity_digest_key("fix::r0::a~b"),
            "a/b and a~b must not alias onto the same digest"
        );
        // Ids without separators are untouched, so every existing digest keeps its name.
        assert_eq!(activity_digest_key("api"), "api");
        assert_eq!(activity_digest_key("verify::api"), "verify::api");
    }

    /// F877: a fix worker repairing `meridian.py` against five failing assertions in
    /// `test_meridian.py` never received the test file — the dependency loop skips tests by
    /// construction — so it was asked to satisfy an expectation it could not read (measured:
    /// 1,756s, promoted:false). The finding text already names the evidence; extract it.
    #[test]
    fn fix_evidence_pointers_names_the_files_the_findings_cite() {
        let findings = vec![
            "`pytest -q` failed: FAILED test_meridian.py::TestFetchAllPaymentsPagination::\
             test_multi_page_pagination — assert body == {...}"
                .to_string(),
            "vendorsync/web/app.js:32 references DOM id `summary-line` which NO html file in the \
             app defines (see vendorsync/web/index.html)."
                .to_string(),
        ];
        let block = fix_evidence_pointers(&findings);
        for p in [
            "test_meridian.py",
            "vendorsync/web/app.js",
            "vendorsync/web/index.html",
        ] {
            assert!(block.contains(p), "must point the fixer at {p}: {block}");
        }
        assert!(
            block.contains("read prohibitions in your rules do NOT apply"),
            "the pointer is useless unless it overrides the no-reading rules: {block}"
        );
        // A finding naming no file adds nothing — no empty ceremony section.
        assert!(fix_evidence_pointers(&["the server never bound a port".to_string()]).is_empty());
    }

    /// F871 holistic-review round: the DELETION ESCAPE (a fix twin deleting/gutting the
    /// stylesheet cleared the finding and was PROMOTED), and the TS/React false-fire (scope
    /// dropped .tsx and JSX className was never harvested — confirmed on two real archived
    /// apps).
    #[tokio::test]
    async fn css_coherence_closes_the_deletion_escape_and_reads_jsx() {
        let have_py = std::process::Command::new("python3")
            .arg("--version")
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false);
        if !have_py {
            return;
        }
        let dir = std::env::temp_dir().join(format!("goose_cssdel_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("web")).unwrap();
        // (a) DELETED: the html links a stylesheet that does not exist — must fire even with
        // no .css in scope at all.
        std::fs::write(
            dir.join("web/index.html"),
            "<head><link rel=\"stylesheet\" href=\"styles.css\"></head><body><h1>App</h1></body>",
        )
        .unwrap();
        let files_no_css: Vec<String> = vec!["web/index.html".to_string()];
        let gone = css_coherence_scan(&dir, &files_no_css).await;
        assert!(gone.ran, "html-only scope must still run the scan");
        assert!(
            gone.findings.len() == 1 && gone.findings[0].contains("does NOT exist"),
            "a linked-but-deleted stylesheet is a finding, not a clean tree: {:?}",
            gone.findings
        );
        // (b) GUTTED: the stylesheet exists but holds almost nothing.
        std::fs::write(dir.join("web/styles.css"), "body { color: #111 }").unwrap();
        let files: Vec<String> = vec!["web/index.html".into(), "web/styles.css".into()];
        let gutted = css_coherence_scan(&dir, &files).await;
        assert!(
            gutted.findings.len() == 1 && gutted.findings[0].contains("effectively unstyled"),
            "a nearly-empty linked stylesheet must fire: {:?}",
            gutted.findings
        );
        // (c) JSX/TS: a React-shaped app whose vocabulary lives in className attributes of a
        // .tsx file — quoted AND braced forms — must be silent (the real loop-05 false-fire).
        std::fs::write(
            dir.join("web/styles.css"),
            ".mine-counter { color: red } .cell { border: 0 } .cell-open { background: #eee }\n\
             .board { display: grid } .status { font-weight: 700 } .btn-reset { padding: 4px }\n\
             .timer { font-family: monospace } .flag { color: orange } .grid-row { display: flex }\n\
             .overlay { position: fixed } .won { color: green } .lost { color: black }",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.tsx"),
            "export function Board() {\n\
             return <div className=\"board overlay\">\n\
               <span className=\"mine-counter timer\">0</span>\n\
               <button className=\"btn-reset\">r</button>\n\
               <div className={r.won ? 'won status' : 'lost status'}>\n\
                 <i className={`cell ${open ? 'cell-open' : 'flag'}`} />\n\
                 <b className=\"grid-row\"/></div></div>;\n}",
        )
        .unwrap();
        let files_tsx: Vec<String> = vec![
            "web/index.html".into(),
            "web/styles.css".into(),
            "web/app.tsx".into(),
        ];
        let jsx = css_coherence_scan(&dir, &files_tsx).await;
        let _ = std::fs::remove_dir_all(&dir);
        assert!(
            jsx.ran && jsx.findings.is_empty(),
            "a styled JSX/TSX app must stay silent — className quoted and braced forms are \
             real usage: {:?}",
            jsx.findings
        );
    }

    /// C1 END-TO-END (F711/F712): the SCAN must skip the swarm's own tests, not merely the helper.
    ///
    /// My first test for this covered `is_test_path` in isolation and passed — which proves nothing
    /// about the scan, because the defect it replaces was a CALL SITE handing a full path to a
    /// basename predicate. That is the third time in one day a pure-predicate test would have missed
    /// the real bug (the shadow/branch drift, the orphan refusal that could never fire, and this).
    /// So this drives `http_timeout_scan` itself and asserts BOTH directions on the same run.
    #[tokio::test]
    async fn timeout_scan_skips_the_swarms_own_tests_and_still_flags_app_code() {
        let dir = std::env::temp_dir().join(format!("c1scan{}", std::process::id()));
        let pkg = dir.join("pkg");
        let tests = dir.join("tests");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::create_dir_all(&tests).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        // APP CODE with a real no-timeout defect — MUST still be flagged.
        std::fs::write(
            pkg.join("bad.py"),
            "import http.client\ndef a(h):\n return http.client.HTTPConnection(h)\n",
        )
        .unwrap();
        // THE SWARM'S OWN TEST FILE, same defect. 28 of 60 real findings named exactly this shape,
        // and the scorer never grades it. MUST be absent.
        std::fs::write(
            tests.join("test_api.py"),
            "import http.client\ndef t(h):\n return http.client.HTTPConnection(h)\n",
        )
        .unwrap();

        let planned: Vec<String> = ["pkg/__init__.py", "pkg/bad.py", "tests/test_api.py"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let app_only: Vec<String> = planned
            .iter()
            .filter(|f| !is_test_path(TargetLang::Python, f))
            .cloned()
            .collect();
        let skipped = planned.len() - app_only.len();
        let res = http_timeout_scan(&dir, TargetLang::Python, &app_scope_py(&dir, &app_only)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available in this environment
        }
        let joined = res.findings.join("\n");

        assert_eq!(skipped, 1, "the filter must remove exactly the tests/ file");
        // A FILTER THAT ATE THE WHOLE SCOPE LOOKS IDENTICAL TO A CLEAN APP — this is the guard.
        assert!(
            res.checked > 0,
            "checked==0 after filtering: the filter removed everything, so a clean result here is \
             silence, not evidence"
        );
        assert!(
            joined.contains("bad.py"),
            "APP code with a no-timeout client must STILL be flagged — if the filter is too greedy \
             the detector goes silent and the fix loop stops seeing real defects: {joined}"
        );
        assert!(
            !joined.contains("test_api.py"),
            "the swarm's OWN test file must NOT be flagged — 55% of real round-0 findings were this, \
             and the scorer grades none of them: {joined}"
        );
    }

    #[test]
    fn every_baked_on_lever_declares_itself_baked_on() {
        const SRC: &str = include_str!("swarm.rs");

        // `split_once` rather than byte-slicing: this file contains multi-byte characters (the marker's
        // own ⚠️ among them), and indexing a &str by byte offset is a panic waiting for the day a
        // boundary moves.
        let d = SRC
            .split_once("impl Default for SwarmConfig {")
            .expect("Default impl")
            .1;
        let d = d.split_once("\n    }\n}").expect("end of Default impl").0;
        let on: std::collections::HashSet<&str> = d
            .lines()
            .filter_map(|l| l.trim().split_once(':'))
            .filter(|(_, v)| matches!(v.trim().trim_end_matches(','), "true" | "Some(true)"))
            .map(|(n, _)| n.trim())
            .collect();

        let s = SRC
            .split_once("pub struct SwarmConfig {")
            .expect("SwarmConfig struct")
            .1;
        let s = s.split_once("\n}").expect("end of struct").0;

        let mut doc = String::new();
        let mut checked = 0usize;
        let mut missing: Vec<&str> = Vec::new();
        for line in s.lines() {
            let t = line.trim();
            if t.starts_with("//") || t.starts_with("#[") {
                doc.push_str(t);
                doc.push('\n');
                continue;
            }
            if let Some((name, ty)) = t.strip_prefix("pub ").and_then(|r| r.split_once(':')) {
                if matches!(ty.trim().trim_end_matches(','), "bool" | "Option<bool>")
                    && on.contains(name.trim())
                {
                    checked += 1;
                    if !doc.contains("BAKED ON") {
                        missing.push(name.trim());
                    }
                }
            }
            doc.clear();
        }

        // ANTI-VACUITY. If the struct is renamed or the layout changes, this parser quietly matches
        // nothing and an empty `missing` would read as a pass — `all([])` is true. A floor makes the
        // parser's own failure loud instead, and it is the only reason this test can be trusted.
        // 44 when the floor was set; 39 since r6e retired five levers to false/None (not baked on).
        assert!(
            checked >= 35,
            "parser found only {checked} baked-on bool levers (expected 35+) — the PARSER is broken, \
             not the docs; fix it before trusting an empty failure list"
        );
        assert!(
            missing.is_empty(),
            "{} lever(s) are ON in `Default for SwarmConfig` but their doc block never says so: {:?}. \
             Add a `BAKED ON` line to each, or the next reader will believe the stale default and act \
             on it (F392).",
            missing.len(),
            missing
        );
    }

    #[test]
    fn summarize_tool_call_extracts_the_intent_field() {
        // shell: the whole command line is the summary.
        assert_eq!(
            summarize_tool_call(
                "developer__shell",
                &serde_json::json!({"command": "pytest -q tests/"})
            ),
            "pytest -q tests/"
        );
        // text_editor: verb + path.
        assert_eq!(
            summarize_tool_call(
                "developer__text_editor",
                &serde_json::json!({"command": "write", "path": "src/main.py", "file_text": "x"})
            ),
            "write src/main.py"
        );
        // path-only tools fall back to the path.
        assert_eq!(
            summarize_tool_call("some__reader", &serde_json::json!({"path": "notes.md"})),
            "notes.md"
        );
        // query-style tools surface the query; newlines/extra whitespace are flattened.
        assert_eq!(
            summarize_tool_call("web__search", &serde_json::json!({"query": "a\n  b   c"})),
            "a b c"
        );
        // No known field: compact JSON, never empty.
        assert!(!summarize_tool_call("x__y", &serde_json::json!({"foo": 1})).is_empty());
        // Overlong summaries are capped with an ellipsis.
        let long = "x ".repeat(300);
        let s = summarize_tool_call("developer__shell", &serde_json::json!({"command": long}));
        assert!(s.chars().count() <= 200, "summary must be capped");
        assert!(s.ends_with('…'));
    }

    #[test]
    fn inflight_args_preview_names_the_target_and_size_never_the_content() {
        let body = (1..=83)
            .map(|i| format!("line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        let p = inflight_args_preview(
            "write",
            &serde_json::json!({"path": "app/cli.py", "content": body}),
        );
        assert_eq!(
            p,
            format!("write app/cli.py (83 lines, {} bytes)", body.len())
        );
        assert!(
            !p.contains("line 42"),
            "content must never ride in the digest"
        );
        assert_eq!(
            inflight_args_preview(
                "edit",
                &serde_json::json!({"path": "a.py", "before": "x\ny", "after": "x\ny\nz"})
            ),
            "edit a.py (2 lines → 3 lines)"
        );
        assert_eq!(
            inflight_args_preview(
                "shell",
                &serde_json::json!({"command": "cd /w && python3 -m pytest -q\n"})
            ),
            "shell: cd /w && python3 -m pytest -q"
        );
        assert_eq!(
            inflight_args_preview("tree", &serde_json::json!({"path": "src", "depth": 2})),
            "tree src"
        );
        // The upstream text_editor shape: verb + path.
        assert_eq!(
            inflight_args_preview(
                "developer__text_editor",
                &serde_json::json!({"command": "view", "path": "a.py"})
            ),
            "view a.py"
        );
        // No path and no command: the tool name plus the generic summary, never empty.
        let f = inflight_args_preview(
            "recipe__final_output",
            &serde_json::json!({"message": "done"}),
        );
        assert!(f.starts_with("recipe__final_output "), "{f}");
        // Bounded at 240 chars whichever field is overlong.
        let long_cmd = "x ".repeat(400);
        let s = inflight_args_preview("shell", &serde_json::json!({"command": long_cmd}));
        assert!(
            s.chars().count() <= INFLIGHT_PREVIEW_MAX,
            "{}",
            s.chars().count()
        );
        assert!(s.ends_with('…'));
        let long_path = "d/".repeat(300);
        let w = inflight_args_preview(
            "write",
            &serde_json::json!({"path": long_path, "content": "a"}),
        );
        assert!(w.chars().count() <= INFLIGHT_PREVIEW_MAX);
    }

    #[test]
    fn activity_digest_inflight_rows_track_pending_requests() {
        let done = vec![ToolCallRecord {
            name: "shell".into(),
            is_mcp: false,
            ok: Some(true),
            fetched_external: false,
        }];
        let records = vec![(
            "shell".to_string(),
            "ls".to_string(),
            Some(true),
            "a b".to_string(),
        )];
        let mut pending: HashMap<String, InflightCall> = HashMap::new();
        pending.insert(
            "call_2".into(),
            InflightCall {
                name: "write".into(),
                is_mcp: false,
                fetched_external: false,
                summary: "app/cli.py".into(),
                args_preview: "write app/cli.py (83 lines, 2100 bytes)".into(),
                since: "2026-08-29T22:40:01+00:00".into(),
            },
        );
        pending.insert(
            "call_1".into(),
            InflightCall {
                name: "shell".into(),
                is_mcp: false,
                fetched_external: false,
                summary: "pytest -q".into(),
                args_preview: "shell: pytest -q".into(),
                since: "2026-08-29T22:39:58+00:00".into(),
            },
        );
        let build = |pending: &HashMap<String, InflightCall>| {
            build_worker_digest(
                &done,
                &records,
                pending,
                &[],
                0,
                0,
                "",
                "m",
                &SaidProvenance::at_dispatch(0),
                None,
                None,
                None,
            )
        };
        let d = build(&pending);
        let rows = d["inflight"].as_array().expect("inflight is an array");
        assert_eq!(rows.len(), 2, "one row per request without a result");
        // Oldest first, and the exact shape the panel reads.
        assert_eq!(
            rows[0],
            serde_json::json!({
                "id": "call_1",
                "tool": "shell",
                "args": "shell: pytest -q",
                "since": "2026-08-29T22:39:58+00:00",
            })
        );
        assert_eq!(rows[1]["id"], "call_2");
        assert_eq!(rows[1]["args"], "write app/cli.py (83 lines, 2100 bytes)");
        // `recent` is completed calls only — untouched by what is in flight.
        assert_eq!(d["recent"], serde_json::json!(["shell ok"]));
        assert_eq!(d["tool_calls"], 1);
        // The provisional ok:null `calls` rows the panel already renders are still there.
        let provisional = d["calls"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|c| c["ok"].is_null())
            .count();
        assert_eq!(provisional, 2);

        // The result lands: the row is gone, the key stays as an empty array.
        pending.remove("call_1");
        let d = build(&pending);
        assert_eq!(d["inflight"].as_array().unwrap().len(), 1);
        assert_eq!(d["inflight"][0]["id"], "call_2");
        pending.remove("call_2");
        let d = build(&pending);
        assert_eq!(d["inflight"], serde_json::json!([]));
        assert_eq!(d["recent"], serde_json::json!(["shell ok"]));
    }

    /// THE r0 CASE, at the digest-builder level. ledger-core-tests attempt 0 ended in the agent's
    /// NetworkError text ("Network error: Stream decode error … Please resend your message to try
    /// again.") and the SAID pane showed it as the live answer for 24+ minutes while attempt 1 ran,
    /// because the digest could say neither WHOSE text it held nor WHAT KIND. This proves the
    /// provenance chain end to end: the error is tagged kind=error, the retry's seed marks it
    /// superseded instead of erasing it, and every subsequent digest write carries it forward.
    #[test]
    fn a_retry_marks_the_prior_attempts_transport_error_superseded() {
        // Attempt 0: the transport error is the ONLY thing on the answer channel (real r0 bytes).
        let error_text = "Network error: Stream decode error: error decoding response body\n\n\
                          Please resend your message to try again."
            .to_string();
        let mut said0 = SaidProvenance::at_dispatch(0);
        let mut seen = 0usize;
        let texts = vec![error_text.clone()];
        said0.observe_texts(texts.len(), &mut seen);
        let d0 = build_worker_digest(
            &[],
            &[],
            &HashMap::new(),
            &texts,
            0,
            0,
            "",
            "workhorse-qwen",
            &said0,
            None,
            None,
            None,
        );
        assert_eq!(d0["attempt"], 0);
        assert_eq!(
            d0["said_kind"], "error",
            "an agent-authored transport error is not something the model SAID"
        );
        assert!(
            d0["said_at"].as_str().is_some(),
            "the answer channel advanced, so said_at is stamped"
        );
        assert!(d0["dispatched_at"].as_str().is_some());
        assert_eq!(d0["superseded"], serde_json::json!([]));

        // The retry (task_retry -> attempt 1): the seed folds attempt 0's digest into `superseded`
        // instead of silently erasing it.
        let mut said1 = SaidProvenance::at_dispatch(1);
        said1.superseded = superseded_from_prior(Some(d0.clone()));
        let seed = seed_worker_digest("workhorse-qwen", &said1, None);
        assert_eq!(seed["attempt"], 1);
        assert_eq!(
            seed["last_text"], "",
            "the new attempt has said nothing yet"
        );
        assert_eq!(seed["phase"], "processing");
        let sup = seed["superseded"].as_array().expect("superseded is a list");
        assert_eq!(sup.len(), 1);
        assert_eq!(sup[0]["attempt"], 0);
        assert_eq!(sup[0]["said_kind"], "error");
        assert_eq!(sup[0]["last_text"].as_str().unwrap(), error_text);
        assert_eq!(sup[0]["said_at"], d0["said_at"]);

        // Every later digest write of attempt 1 carries the superseded entry (the shared builder is
        // the point — no write site can drop it).
        let d1 = build_worker_digest(
            &[],
            &[],
            &HashMap::new(),
            &[],
            0,
            0,
            "",
            "workhorse-qwen",
            &said1,
            None,
            None,
            None,
        );
        assert_eq!(d1["attempt"], 1);
        assert_eq!(d1["superseded"], seed["superseded"]);
        assert_eq!(
            d1["said_kind"], "said",
            "no text yet — nothing to classify as an error"
        );
        assert_eq!(d1["said_at"], serde_json::Value::Null);

        // Ordinary model prose is `said`, and all three agent error closers are `error`.
        assert_eq!(
            said_kind_of("I've written comprehensive tests for ledger-core."),
            "said"
        );
        assert_eq!(
            said_kind_of("Ran into this error: x.\n\nPlease retry if you think this is a transient or recoverable error."),
            "error"
        );
        assert_eq!(
            said_kind_of(
                "The provider refused this request.\n\nPlease start a new session to continue — \
                 resending this conversation is likely to be refused again."
            ),
            "error"
        );

        // A LEGACY prior digest (no provenance keys) still supersedes, with attempt unknown.
        let legacy = serde_json::json!({ "last_text": error_text, "model": "m" });
        let sup = superseded_from_prior(Some(legacy));
        assert_eq!(sup.len(), 1);
        assert_eq!(sup[0]["attempt"], serde_json::Value::Null);
        assert_eq!(sup[0]["said_kind"], "error");

        // A prior digest that said NOTHING adds no entry — a clean re-dispatch stays clean.
        assert_eq!(
            superseded_from_prior(Some(seed_worker_digest(
                "m",
                &SaidProvenance::at_dispatch(0),
                None
            ))),
            Vec::<serde_json::Value>::new()
        );

        // The attempt marker round-trips through the UI's split regex shape.
        let marker = transcripts::attempt_marker_line(1, &said1.dispatched_at);
        assert!(marker.starts_with("\n===== swarm attempt 1 · dispatched "));
        assert!(marker.ends_with(" =====\n"));
    }

    /// r6 supervision lanes: BOTH shared digest builders stamp `"supervision": true` from the one
    /// key-class derivation — and a worker lane's digest stays byte-identical (field absent, not
    /// false), so nothing that reads today's digests can be disturbed by the new lanes.
    #[test]
    fn supervision_lanes_are_stamped_by_both_digest_builders_and_worker_lanes_are_not() {
        let said = SaidProvenance::at_dispatch(3);
        let d = build_worker_digest(
            &[],
            &[],
            &HashMap::new(),
            &[],
            0,
            0,
            "",
            "m",
            &said,
            Some("judge-open-1"),
            None,
            None,
        );
        assert_eq!(d["supervision"], serde_json::json!(true));
        assert_eq!(
            d["attempt"], 3,
            "the judge lane's attempt field carries the look number"
        );
        let seed = seed_worker_digest("m", &said, Some(ASK_ANSWER_LANE));
        assert_eq!(seed["supervision"], serde_json::json!(true));
        let w = build_worker_digest(
            &[],
            &[],
            &HashMap::new(),
            &[],
            0,
            0,
            "",
            "m",
            &said,
            Some("test-store-core"),
            None,
            None,
        );
        assert!(
            w.get("supervision").is_none(),
            "a worker lane digest is byte-identical to before"
        );
        assert!(seed_worker_digest("m", &said, None)
            .get("supervision")
            .is_none());
    }

