    #[test]
    fn clip_tail_keeps_the_informative_end() {
        assert_eq!(clip_tail("short output", 400), "short output");
        let long: String = "x".repeat(500);
        let c = clip_tail(&long, 400);
        assert_eq!(c.chars().count(), 401, "400 chars + a leading ellipsis");
        assert!(c.starts_with('…'));
    }

    #[test]
    fn build_reasoning_drops_trivial_fragments() {
        // The lone dots / backticks / stray words coder models emit between tool calls are dropped —
        // so the panel never shows a reasoning box holding just ".".
        assert_eq!(
            build_reasoning(&[".".into(), "`.".into(), " result".into(), "backs".into()]),
            ""
        );
        // A real narration sentence survives.
        assert_eq!(
            build_reasoning(&[
                ".".into(),
                "Writing the tokenizer module now.".into(),
                "`".into()
            ]),
            "Writing the tokenizer module now."
        );
    }

    #[test]
    fn build_answer_window_matches_full_walk_at_window_boundary() {
        // build_answer_window walks from the back and stops once it has covered ANSWER_WINDOW_CHARS,
        // instead of scanning the whole (growing) texts vec every write. Prove the output is byte-identical
        // to the naive full walk it replaced, ACROSS the window boundary where the early-stop actually
        // kicks in. (G-2: the fn was `build_full_reasoning` — same behaviour, honest name; the window is
        // a digest I/O bound, and the complete record is the append-only `<task>.log`.)
        fn reference(texts: &[String]) -> String {
            let joined = texts
                .iter()
                .map(|t| t.trim())
                .filter(|t| t.chars().count() >= 6 && t.contains(char::is_whitespace))
                .collect::<Vec<_>>()
                .join("\n\n");
            clip_tail(&joined, ANSWER_WINDOW_CHARS)
        }
        // 400 chunks of ~120 chars each ≈ 48000 chars total — well past the window, plus interleaved
        // trivial fragments (dropped) and a couple of short no-whitespace tokens (also dropped).
        let mut texts: Vec<String> = Vec::new();
        for i in 0..400 {
            texts.push(".".into());
            texts.push(format!(
                "chunk {i} narration line describing what the worker is doing at this particular step {}",
                "x".repeat(60)
            ));
            texts.push("`".into());
        }
        assert_eq!(build_answer_window(&texts), reference(&texts));
        // And the small case (under the window) is identical too.
        let small = vec![
            "first substantive narration line".to_string(),
            ".".to_string(),
            "second substantive narration line".to_string(),
        ];
        assert_eq!(build_answer_window(&small), reference(&small));
        assert_eq!(build_answer_window(&[]), reference(&[]));
    }

    #[test]
    fn integrate_verify_does_not_block_on_tests() {
        // A failing `tests` subtask must not block integrate-verify (UNIQ6: tests failed -> integrate-verify
        // never ran -> the app's real bug went uncaught + the run looked failed for the wrong reason).
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"cli-entry","depends_on":["core"],"files":["cli.py"]},
                {"id":"tests","depends_on":["core"],"files":["tests/test_core.py"]},
                {"id":"integrate-verify","depends_on":["core","cli-entry","tests"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let stripped = strip_integrate_verify_test_deps(&mut plan, TargetLang::Python);
        assert_eq!(stripped, 1, "the single 'tests' dep should be stripped");
        let iv = plan["subtasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["id"] == "integrate-verify")
            .unwrap();
        let deps: Vec<&str> = iv["depends_on"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|d| d.as_str())
            .collect();
        assert_eq!(
            deps,
            vec!["core", "cli-entry"],
            "real module/entry deps stay; tests dep removed"
        );
    }

    #[test]
    fn relax_test_module_deps_truth_table() {
        fn deps(plan: &serde_json::Value, id: &str) -> String {
            plan["subtasks"]
                .as_array()
                .unwrap()
                .iter()
                .find(|s| s["id"] == id)
                .unwrap()["depends_on"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|d| d.as_str())
                .collect::<Vec<_>>()
                .join(",")
        }
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"store","depends_on":[],"files":["store.py"]},
                {"id":"shared","depends_on":[],"files":["shared.py"]},
                {"id":"cli-entry","depends_on":["store","shared"],"files":["cli.py","__main__.py"]},
                {"id":"test-store","depends_on":["store","cli-entry"],"files":["test_store.py"]},
                {"id":"test-shared-user","depends_on":["shared","cli-entry"],"files":["test_shared.py"]},
                {"id":"test-cli","depends_on":["cli-entry"],"files":["test_cli.py"]},
                {"id":"tests","depends_on":["store","cli-entry"],"files":["test_store.py","test_cli.py"]},
                {"id":"integrate-verify","depends_on":["store","shared","cli-entry"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = relax_test_module_deps(&mut plan, TargetLang::Python);
        // uniquely-leaf test: cli edge dropped, its module dep kept
        assert_eq!(deps(&plan, "test-store"), "store");
        // THE regression guard: a leaf test that genuinely imports a sibling keeps the sibling, drops only cli
        assert_eq!(deps(&plan, "test-shared-user"), "shared");
        // the cli's OWN test keeps its cli dep (self is cli)
        assert_eq!(deps(&plan, "test-cli"), "cli-entry");
        // monolithic/ambiguous test (spans store+cli) left untouched
        assert_eq!(deps(&plan, "tests"), "store,cli-entry");
        // integrate-verify never touched
        assert_eq!(deps(&plan, "integrate-verify"), "store,shared,cli-entry");
        assert_eq!(n, 2, "exactly the two stray cli edges relaxed");
    }

    #[test]
    fn relax_test_module_deps_noop_on_monolithic_plan() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"cli-entry","depends_on":["core"],"files":["cli.py"]},
                {"id":"tests","depends_on":["cli-entry"],"files":["tests/test_core.py","tests/test_cli.py"]},
                {"id":"integrate-verify","depends_on":["core","cli-entry","tests"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let before = plan.clone();
        let n = relax_test_module_deps(&mut plan, TargetLang::Python);
        assert_eq!(n, 0, "no uniquely-leaf per-module test -> nothing relaxed");
        assert_eq!(plan, before, "monolithic plan left byte-identical");
    }

    #[tokio::test]
    async fn ast_review_counts_from_pkg_import_submodule_as_wired() {
        // A package whose __main__ wires its cli via `from pkg import cli` must NOT be flagged unwired
        // (the observed UNIQ12 false-positive); a genuinely orphaned module still must be. Skips if python3
        // is unavailable (run_ast_review returns ran=false then).
        let dir = std::env::temp_dir().join(format!("goose_ast_review_{}", std::process::id()));
        let pkg = dir.join("pkg");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        std::fs::write(pkg.join("__main__.py"), "from pkg import cli\ncli.main()\n").unwrap();
        std::fs::write(pkg.join("cli.py"), "def main():\n return 0\n").unwrap();
        std::fs::write(pkg.join("orphan.py"), "x = 1\n").unwrap();
        // Scoped to the plan's own files. The assertions below are UNCHANGED, so they double as proof
        // that scoping did not BLIND the check — the genuine orphan must still be flagged.
        let planned: Vec<String> = [
            "pkg/__init__.py",
            "pkg/__main__.py",
            "pkg/cli.py",
            "pkg/orphan.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let res = run_ast_review(&dir, &app_scope_py(&dir, &planned)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available in this environment
        }
        let joined = res.findings.join("\n");
        assert!(
            !joined.contains("module 'pkg.cli' is imported by no"),
            "cli wired via `from pkg import cli` must not be flagged UNWIRED: {joined}"
        );
        assert!(
            joined.contains("pkg.orphan"),
            "a genuinely orphaned module must still be flagged: {joined}"
        );
    }

    /// REGRESSION, from a FALSE DEMOTE on a WORKING app.
    ///
    /// A run built settle/api.py — the FastAPI app, with the spec's exact /api surface — plus a
    /// __main__.py doing `uvicorn.run("settle.api:app")`. That is a STRING, not an import, so the
    /// import-edge scan reported "settle.api is imported by no non-test module" and
    /// `unwired_demotes_verified` RETRACTED `verified` on the best app of the run. Technically true,
    /// semantically false. Without this, EVERY idiomatic FastAPI/Flask/Celery layout is flagged — the
    /// conventional shape those specs ask for.
    #[tokio::test]
    async fn ast_review_counts_a_runtime_loader_string_as_wired() {
        let dir = std::env::temp_dir().join(format!("goose_ast_uvicorn_{}", std::process::id()));
        let pkg = dir.join("app");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        // The real shape: the entry NAMES its app, it never imports it.
        std::fs::write(
            pkg.join("__main__.py"),
            "import uvicorn\nuvicorn.run(\"app.api:app\", host=\"127.0.0.1\", port=8000)\n",
        )
        .unwrap();
        std::fs::write(
            pkg.join("api.py"),
            "CONST = 1\ndef make():\n return CONST\n",
        )
        .unwrap();
        // ...and a module NOTHING names, anywhere. The fix must not blind the check.
        std::fs::write(pkg.join("orphan.py"), "x = 1\n").unwrap();
        let planned: Vec<String> = [
            "app/__init__.py",
            "app/__main__.py",
            "app/api.py",
            "app/orphan.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let res = run_ast_review(&dir, &app_scope_py(&dir, &planned)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available
        }
        let joined = res.findings.join("\n");
        assert!(
            !joined.contains("'app.api'"),
            "a module named by a uvicorn/gunicorn \"pkg.mod:attr\" string is WIRED — it is the entry \
             point: {joined}"
        );
        assert!(
            !res.demote_eligible.contains(&"app.api".to_string()),
            "and it must never be demote-eligible: {:?}",
            res.demote_eligible
        );
        assert!(
            joined.contains("app.orphan"),
            "a module nothing names must STILL be flagged — the fix must not blind the check: {joined}"
        );
    }

    #[test]
    fn ask_replan_defaults_off_and_opts_in() {
        // Default (unset) now REUSES the plan (skip the re-plan, per the UNIQ12/UNIQ12b A/B); opt INTO the
        // re-plan only with an explicit on-value.
        assert!(
            !ask_replan_resolved(None, None),
            "unset (env+config None) defaults OFF (reuse plan / skip re-plan)"
        );
        assert!(ask_replan_enabled(Some("1".into())));
        assert!(ask_replan_enabled(Some("on".into())));
        assert!(ask_replan_enabled(Some("true".into())));
        assert!(ask_replan_enabled(Some("YES".into())), "case-insensitive");
        assert!(!ask_replan_enabled(Some("0".into())));
        assert!(!ask_replan_enabled(Some("off".into())));
        assert!(
            !ask_replan_enabled(Some("anything".into())),
            "unknown values skip — only explicit on-values re-plan"
        );
        assert!(!ask_replan_enabled(Some(" no ".into())));
    }

    #[test]
    fn answers_win_floor_defaults_on_and_opts_out() {
        // #129: the guard ships ON. Unset env+config resolves TRUE (unlike ask_replan, which defaults off) so a
        // config that omits the field — every user who never toggled it — gets the foot-gun fix.
        assert!(
            answers_win_floor_resolved(None, None),
            "unset (env+config None) defaults ON — the #129 fix reaches users who never touched it"
        );
        assert!(
            answers_win_floor_resolved(None, Some(true)),
            "explicit config true stays on"
        );
        // Explicit opt-OUT restores the legacy re-plan (for A/B / rollback), env winning over config.
        assert!(!answers_win_floor_resolved(Some("0".into()), None));
        assert!(!answers_win_floor_resolved(Some("off".into()), Some(true)));
        assert!(!answers_win_floor_resolved(None, Some(false)));
        // Explicit on-values, case-insensitive, env beats a config false.
        assert!(answers_win_floor_resolved(Some("1".into()), Some(false)));
        assert!(answers_win_floor_resolved(Some("YES".into()), None));
        // An unknown env value is NOT an on-value; env-present means env decides, so it is off.
        assert!(!answers_win_floor_resolved(
            Some("anything".into()),
            Some(true)
        ));
    }

    #[test]
    fn straggler_grace_arms_only_for_the_lone_last_draft() {
        // n < 3: no lone straggler concept — never arm (both drafts are needed for agreement).
        assert!(!should_arm_straggler_grace(1, 1));
        assert!(!should_arm_straggler_grace(2, 2));
        // n == 3: Mihai's "2 of 3" — arm exactly when 2 valid are in and 1 is still out.
        assert!(
            !should_arm_straggler_grace(3, 1),
            "one valid draft is not a quorum"
        );
        assert!(
            should_arm_straggler_grace(3, 2),
            "2 of 3 valid -> race the 3rd"
        );
        assert!(should_arm_straggler_grace(3, 3));
        // n == 6: conservative — only ever race the single last draft (5 of 6), never sacrifice diversity
        // while more than one draft is still outstanding.
        assert!(!should_arm_straggler_grace(6, 2));
        assert!(!should_arm_straggler_grace(6, 4));
        assert!(
            should_arm_straggler_grace(6, 5),
            "5 of 6 valid -> race the 6th"
        );
    }

    #[test]
    fn stream_decode_retry_defaults_on_and_opts_out() {
        // #121 ships ON: unset env+config resolves TRUE so the false-green fix reaches every user, including
        // desktop configs that omit the field.
        assert!(
            stream_decode_retry_resolved(None, None),
            "unset defaults ON — the #121 false-green fix reaches users who never toggled it"
        );
        assert!(stream_decode_retry_resolved(None, Some(true)));
        // Explicit opt-OUT restores the legacy accept-as-done path (for the A/B), env winning over config.
        assert!(!stream_decode_retry_resolved(Some("0".into()), None));
        assert!(!stream_decode_retry_resolved(
            Some("off".into()),
            Some(true)
        ));
        assert!(!stream_decode_retry_resolved(None, Some(false)));
        assert!(stream_decode_retry_resolved(Some("1".into()), Some(false)));
        assert!(stream_decode_retry_resolved(Some("YES".into()), None));
    }

    #[test]
    fn stream_decode_interrupt_predicate_is_deterministic() {
        // BOTH halves required: the marker AND the exact trailing resend sentence (the agent loop appends it
        // as the last chunk after a NetworkError, then breaks).
        let hit = "Network error: Stream decode error: error decoding response body\n\nPlease resend your message to try again.";
        assert!(is_stream_decode_interrupt(hit));
        // Trailing whitespace is tolerated (trim_end before the suffix check).
        assert!(is_stream_decode_interrupt(&format!("{hit}\n  ")));
        // Marker present but NOT the trailing sentence (e.g. a genuine verdict that merely quotes the phrase)
        // -> not an interrupt; the run's real output must be preserved.
        assert!(!is_stream_decode_interrupt(
            "The app logs a 'Stream decode error' when the socket closes; VERDICT: PASS."
        ));
        // The resend sentence WITHOUT the decode marker (some other transient) -> not this predicate.
        assert!(!is_stream_decode_interrupt(
            "Some other failure.\n\nPlease resend your message to try again."
        ));
        // A normal, clean verdict is never a false positive.
        assert!(!is_stream_decode_interrupt(
            "VERDICT: PASS — all endpoints return 200 and balances sum to zero."
        ));
    }

    #[test]
    fn straggler_stop_defaults_off_and_opts_in() {
        // A timing change, not a correctness fix — ships OFF (byte-identical await-all) until validated.
        assert!(!straggler_stop_resolved(None, None));
        assert!(!straggler_stop_resolved(None, Some(false)));
        assert!(straggler_stop_resolved(None, Some(true)));
        assert!(straggler_stop_resolved(Some("1".into()), None));
        assert!(
            straggler_stop_resolved(Some("on".into()), Some(false)),
            "env beats config"
        );
        assert!(!straggler_stop_resolved(Some("0".into()), Some(true)));
        assert!(!straggler_stop_resolved(
            Some("nonsense".into()),
            Some(true)
        ));
    }

    // The async abort/grace path — the pure predicate test above did NOT exercise this, and that is exactly
    // where a panic hid (a huge inert-timer duration overflowed std::Instant). Real (short) durations, no
    // test-util needed; big margins keep them deterministic.
    #[tokio::test]
    async fn straggler_stop_aborts_lone_lagging_draft() {
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_secs(30)).await;
            Some("C".to_string())
        });
        // Two valid drafts land instantly and arm a 1s grace; the 30s straggler is aborted ~1s later.
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 1, "the lone straggler is stopped");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 2, "quorum of 2 kept; straggler dropped");
        assert!(c.contains(&"A".to_string()) && c.contains(&"B".to_string()));
        assert!(!c.contains(&"C".to_string()));
    }

    #[tokio::test]
    async fn straggler_stop_keeps_all_when_none_lags() {
        let mut js = tokio::task::JoinSet::new();
        for k in ["A", "B", "C"] {
            let s = k.to_string();
            js.spawn(async move { Some(s) });
        }
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 0);
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3);
    }

    #[tokio::test]
    async fn straggler_that_finishes_within_grace_is_kept() {
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
            Some("C".to_string())
        });
        // grace 10s >> the 50ms straggler, so it lands inside the window and is kept (all 3 collected).
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(10),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 0, "straggler finished within grace");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3);
    }

    #[tokio::test]
    async fn straggler_invalid_drafts_do_not_arm_the_grace() {
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("VALID".to_string()) });
        js.spawn(async { Some("BAD".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_millis(80)).await;
            Some("VALID2".to_string())
        });
        // Only ONE valid draft lands until the 3rd resolves, so the 2-valid quorum never forms before the
        // last draft — the grace never arms and nothing is stopped, even though a draft was slower.
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |s| s.starts_with("VALID"),
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 0, "one valid draft is not a quorum -> never armed");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3);
    }

    #[tokio::test]
    async fn straggler_quorum_below_floor_defers_the_abort() {
        // B5 both directions. Direction 1: the in-hand pair does NOT decide (quorum_decides false),
        // so the count condition holding must NOT arm the grace — the slow third draft is awaited in
        // full and `deferred` reports why.
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_millis(80)).await;
            Some("C".to_string())
        });
        let (c, dead, stopped, deferred) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| false,
        )
        .await;
        assert_eq!(
            stopped, 0,
            "below-floor quorum must never abort the last draft"
        );
        assert!(deferred, "the deferral must be observable");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3, "the full pool is collected");

        // Direction 2: the pair DOES decide -> today's behavior exactly (abort after grace).
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_secs(30)).await;
            Some("C".to_string())
        });
        let (c, _dead, stopped, deferred) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 1, "deciding quorum keeps the pre-B5 abort");
        assert!(!deferred);
        assert_eq!(c.len(), 2);
    }

    #[test]
    fn the_derived_grace_scales_with_the_round_and_respects_the_backstop() {
        // G1 both directions. A slow round (quorum at 200s, timeout 480) earns a patient grace…
        assert_eq!(derived_straggler_grace(200, 480), 100);
        // …a fast round gets the floor, not a constant sized for a slower fleet…
        assert_eq!(derived_straggler_grace(12, 480), 10);
        // …and near the hard backstop the grace can never outrun draft_timeout.
        assert_eq!(derived_straggler_grace(470, 480), 10);
        assert_eq!(derived_straggler_grace(400, 480), 80);
    }

    #[test]
    fn score_skeleton_prefers_wider_flatter_plan() {
        let wc = 3;
        let wide = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":[],"files":["b.py"]},
                {"id":"c","depends_on":[],"files":["c.py"]},
                {"id":"integrate-verify","depends_on":["a","b","c"],"files":["t.py"]}
            ]}"#,
        )
        .unwrap();
        let deep = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":["a"],"files":["b.py"]},
                {"id":"c","depends_on":["b"],"files":["c.py"]},
                {"id":"integrate-verify","depends_on":["a","b","c"],"files":["t.py"]}
            ]}"#,
        )
        .unwrap();
        let sw = score_skeleton(&wide, wc).unwrap();
        let sd = score_skeleton(&deep, wc).unwrap();
        assert!(sw > sd, "wider/flatter should win: wide={sw} deep={sd}");
        // a dep on an unknown task is not a valid DAG -> None (so it can never be picked).
        let bad = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[{"id":"x","depends_on":["nope"],"files":["x.py"]}]}"#,
        )
        .unwrap();
        assert!(score_skeleton(&bad, wc).is_none());
    }

    #[test]
    fn converge_role_normalizes_surface_variety() {
        // Two drafts with the SAME roles (types, parser, cli) but different dirs/case/entry-name, plus the
        // injected sink + a test module. Role-normalized agreement should read near-perfect; the raw metric
        // reads them as heavily divergent (different file strings + task counts).
        let d1 = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"types","depends_on":[],"files":["pkg/types.py"]},
                {"id":"parser","depends_on":["types"],"files":["pkg/parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["pkg/__main__.py"]},
                {"id":"tests","depends_on":["parser"],"files":["tests/test_parser.py"]},
                {"id":"integrate-verify","depends_on":["cli"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let d2 = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"shared-types","depends_on":[],"files":["src/Types.py"]},
                {"id":"the-parser","depends_on":["shared-types"],"files":["src/Parser.py"]},
                {"id":"entry","depends_on":["the-parser"],"files":["src/cli.py"]},
                {"id":"integrate-verify","depends_on":["entry"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let cands = vec![d1, d2];
        let (raw, _) = plan_agreement(&cands, false);
        let (norm, reason) = plan_agreement(&cands, true);
        assert!(norm > raw, "role-normalized {norm} should beat raw {raw}");
        assert!(
            norm >= 85,
            "same 3 roles -> near-perfect agreement, got {norm}"
        );
        assert!(reason.contains("role-normalized"));
    }

    #[test]
    fn canonical_role_folds_entry_but_keeps_distinct_stages() {
        // Entry-point synonyms fold to one role.
        for f in [
            "__main__.py",
            "app.py",
            "src/main.py",
            "cli.py",
            "run.py",
            "entry.py",
        ] {
            assert_eq!(canonical_role(f), "cli", "{f} should be the cli role");
        }
        // Distinct compilation stages must NOT merge (conservative — no over-counting).
        assert_eq!(canonical_role("src/lexer.py"), "lexer");
        assert_eq!(canonical_role("Parser.PY"), "parser");
        assert_eq!(canonical_role("ast.rs"), "ast");
        assert_ne!(canonical_role("lexer.py"), canonical_role("parser.py"));
        // A genuinely different decomposition (split lexer+parser vs one combined parser) stays < perfect.
        let split = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"lexer","depends_on":[],"files":["lexer.py"]},
                {"id":"parser","depends_on":["lexer"],"files":["parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["cli.py"]}
            ]}"#,
        )
        .unwrap();
        let combined = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"parser","depends_on":[],"files":["parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["cli.py"]}
            ]}"#,
        )
        .unwrap();
        let (norm, _) = plan_agreement(&[split, combined], true);
        assert!(
            norm < 100,
            "genuinely different decompositions must not read perfect: {norm}"
        );
    }

    #[test]
    fn plan_agreement_default_path_unchanged() {
        let d = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":["a"],"files":["b.py"]}
            ]}"#,
        )
        .unwrap();
        // Two identical drafts, raw path: spread 0 (40) + jaccard 1 (45) + indep 0 (15) = 100, no marker.
        let (c, r) = plan_agreement(&[d.clone(), d.clone()], false);
        assert_eq!(c, 100);
        assert!(!r.contains("role-normalized"));
        // Single draft -> inert neutral 60 on both paths.
        assert_eq!(plan_agreement(std::slice::from_ref(&d), false).0, 60);
        assert_eq!(plan_agreement(std::slice::from_ref(&d), true).0, 60);
    }

    #[test]
    fn best_subset_agreement_drops_the_outlier() {
        // Three tight drafts (same 3 roles) + one wild outlier (5 modules, disjoint files). The full-set
        // measure is dragged down by the outlier; the best 3-of-4 consensus recovers the tight cluster.
        let tight = |seed: &str| {
            goose_swarm::specs_from_plan_json(&format!(
                r#"{{"subtasks":[
                    {{"id":"types{seed}","depends_on":[],"files":["types.py"]}},
                    {{"id":"core{seed}","depends_on":["types{seed}"],"files":["core.py"]}},
                    {{"id":"cli{seed}","depends_on":["core{seed}"],"files":["cli.py"]}}
                ]}}"#
            ))
            .unwrap()
        };
        let outlier = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["alpha.py"]},
                {"id":"b","depends_on":[],"files":["beta.py"]},
                {"id":"c","depends_on":["a"],"files":["gamma.py"]},
                {"id":"d","depends_on":["b"],"files":["delta.py"]},
                {"id":"e","depends_on":["c","d"],"files":["epsilon.py"]}
            ]}"#,
        )
        .unwrap();
        let pool = vec![tight("1"), tight("2"), tight("3"), outlier];
        let (full, _) = plan_agreement(&pool, true);
        let (subset, reason) = best_subset_agreement(&pool, true, 3);
        assert!(
            subset > full,
            "consensus cluster {subset} should beat the outlier-dragged full set {full}"
        );
        assert!(subset >= 85, "the 3 tight drafts agree on roles: {subset}");
        assert!(reason.contains("consensus 3 of 4"));
        // Inert when the pool has not grown past k: identical to the full-set measure (byte-identical default).
        let two = vec![tight("1"), tight("2")];
        assert_eq!(
            best_subset_agreement(&two, true, 3),
            plan_agreement(&two, true)
        );
    }

    #[test]
    fn spec_contract_parsing() {
        let spec =
            "It runs as `python3 -m quorum` which starts the server. REST: POST /api/polls; \
                    GET /api/polls/<id>; GET /api/polls/<id>/results; GET /api/polls (list).";
        assert_eq!(spec_python_entry(spec).as_deref(), Some("quorum"));
        let gets = spec_get_endpoints(spec);
        // The concrete list endpoint is kept; the param'd routes are excluded (no false base-path finding).
        assert_eq!(gets, vec!["/api/polls".to_string()]);
        assert!(!gets.iter().any(|g| g.contains("id") || g.contains('<')));
        // No advertised python entry -> None (a Swift/TS spec no-ops the whole check).
        assert!(spec_python_entry("Build a Swift CLI note-taker").is_none());
        // Port: default 8000, else the advertised one.
        assert_eq!(spec_port("no port mentioned"), 8000);
        assert_eq!(spec_port("the server listens on 127.0.0.1:9100"), 9100);
        // A pure-CLI spec with no GET endpoints yields nothing to curl.
        assert!(spec_get_endpoints("python3 -m tool add x").is_empty());
    }

    #[test]
    fn clarity_fail_closed_reasons() {
        // FAIL-CLOSED (learned nothing → ask): timeout / agent_error / no_final_output, incl. the ": detail" tail.
        assert!(clarity_reason_is_fail_closed("timeout"));
        assert!(clarity_reason_is_fail_closed(
            "agent_error: connection refused"
        ));
        assert!(clarity_reason_is_fail_closed("no_final_output"));
        // FAIL-OPEN (the model DID answer, the JSON just didn't fit): unparseable stays out → no false-ask storm.
        assert!(!clarity_reason_is_fail_closed("unparseable: {truncated"));
    }

    // ---- #136 DELEGATED DECISIONS ----------------------------------------------------------------
    // The real spec that caused the bug, trimmed to the shapes that matter.
    const LOGFOLD_SPEC: &str = "\
Build `logfold` — a log template miner, in Go, stdlib only.\n\
\n\
## The core\n\
Mask first, then tokenize, then route by a fixed-depth tree. Determinism is required.\n\
\n\
## Calls I'm leaving to you\n\
- **Placeholder vocabulary — typed or flat.** Whether a masked slot renders as a single `<*>` everywhere, or\n\
  keeps its type (`<NUM>`, `<IP>`, `<UUID>`). Typed reads better and diffs more precisely but grows the\n\
  masker surface. Your call, but be consistent between the mask stage and the tree-generalization stage.\n\
- **Template identity across runs.** How a template gets a stable id used by `diff` to match baseline to new\n\
  — hash of the token sequence? This decision is the whole ballgame; make it and defend it in a comment.\n\
";

    #[test]
    fn delegated_decisions_do_not_block_but_a_silent_spec_still_asks() {
        // A: the spec DELEGATES -> recorded, never asked. This is the measured mtp-base case.
        let decisions = vec![
            "Placeholder vocabulary: typed placeholders (<NUM>, <IP>, <UUID>) vs a flat wildcard everywhere. \
             Typed gives better diff precision but grows the masker surface."
                .to_string(),
            "Template identity across runs for diff matching: how a template gets a stable id used by diff to \
             match baseline to new, and what counts as the same template."
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&decisions, LOGFOLD_SPEC);
        assert_eq!(
            delegated.len(),
            2,
            "both are delegated by the spec's own section"
        );
        assert!(blocking.is_empty(), "nothing should block: {blocking:?}");

        // B: a decision the spec NEVER MENTIONS must still block. The gate must not become a blanket silencer.
        let unmentioned = vec![
            "Which authentication provider should the billing portal use for single sign-on"
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&unmentioned, LOGFOLD_SPEC);
        assert_eq!(blocking.len(), 1, "an unmentioned decision MUST still ask");
        assert!(delegated.is_empty());
    }

    #[test]
    fn a_reservation_phrase_outranks_delegation_in_the_same_region() {
        // C: "do NOT guess — ask me" must win, even sitting inside a delegating section, or one loose
        // "your call" would silence the questions the author most wanted asked.
        let spec = "## Calls I'm leaving to you\n\
                    Styling and output formatting are your call.\n\
                    The storage backend and retention window are NOT: do not guess them, ask me.\n";
        let d = vec![
            "storage backend and retention window for the archived records, no sensible default exists"
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&d, spec);
        assert_eq!(blocking.len(), 1, "a reserved decision must still block");
        assert!(delegated.is_empty());
    }

    #[test]
    fn no_delegation_section_is_a_total_passthrough() {
        // F: with nothing delegating, the partition must return the input unchanged — this is what makes the
        // lever byte-identical on the specs that do not use delegation language at all.
        let spec = "Build a CLI that converts markdown to HTML. Support tables and footnotes.";
        let d = vec![
            "whether footnote backlinks render inline or collected at the document foot"
                .to_string(),
            "which markdown flavour to accept for tables".to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&d, spec);
        assert_eq!(blocking, d, "unchanged");
        assert!(delegated.is_empty());
    }

    #[test]
    fn model_prose_appended_to_the_prompt_can_never_manufacture_a_delegation() {
        // THE EXPOSURE, pinned. opts.prompt is appended to by MODEL output at :19660 (research findings) and
        // :19799 (clarify Q&A), and a retarget round re-plans with the enlarged prompt. Research output
        // routinely contains "either is defensible" -- which is one of DELEGATION_MARKERS verbatim. If the
        // partition read the live prompt, the model would be able to silence a question the user needed to
        // answer, which is the exact direction this gate must never fail in.
        let operator_spec =
            "Build a CLI that syncs two folders. It must never delete without a prompt.";
        let model_appended = "\n\n## RESEARCH FINDINGS\n\
             - Conflict resolution: either is defensible, your call whether last-write-wins or newest-mtime \
               wins; pick something sensible and defend it in a comment.\n";
        let polluted = format!("{operator_spec}{model_appended}");
        let decision = vec![
            "Conflict resolution strategy when both sides changed: last-write-wins versus newest-mtime wins, \
             no sensible default exists and guessing wrong silently loses a user's edits"
                .to_string(),
        ];

        // Parsed from the POLLUTED prompt the model would have silenced it...
        let (blocking_bad, delegated_bad) = partition_delegated_decisions(&decision, &polluted);
        assert!(
            !delegated_bad.is_empty() || blocking_bad.len() == 1,
            "sanity: the polluted text is the risky input"
        );

        // ...but parsed from the FROZEN operator spec, which says nothing about delegation, it MUST still ask.
        let (blocking, delegated) = partition_delegated_decisions(&decision, operator_spec);
        assert_eq!(
            blocking.len(),
            1,
            "the operator never delegated this — it must still block"
        );
        assert!(
            delegated.is_empty(),
            "model prose must never create a delegation: {delegated:?}"
        );
    }

    #[test]
    fn a_thin_decision_is_never_assumed_delegated() {
        // Guard the conservative bias: too few significant tokens to match on => keep asking. A false
        // "delegated" silences a real question, which is strictly worse than an unnecessary ask.
        let regions = delegation_regions(LOGFOLD_SPEC);
        assert!(!regions.is_empty());
        assert!(!decision_is_delegated("typed or flat", &regions));
        assert!(!decision_is_delegated("the id", &regions));
    }

    #[test]
    fn consensus_backbone_pins_only_the_strict_majority() {
        let draft = |ids: &[(&str, &str)]| {
            let subs: Vec<String> = ids
                .iter()
                .map(|(id, file)| format!(r#"{{"id":"{id}","depends_on":[],"files":["{file}"]}}"#))
                .collect();
            goose_swarm::specs_from_plan_json(&format!(r#"{{"subtasks":[{}]}}"#, subs.join(",")))
                .unwrap()
        };
        // 3 drafts: models+cli appear in 2/3; parser in 1/3; a per-module test task must NOT contribute a role.
        let d1 = draft(&[
            ("models", "models.py"),
            ("cli", "__main__.py"),
            ("t", "test_models.py"),
        ]);
        let d2 = draft(&[("models", "models.py"), ("entry", "cli.py")]);
        let d3 = draft(&[("parser", "parser.py"), ("main", "main.py")]);
        let bb = consensus_backbone(&[d1, d2, d3]);
        // cli (folded from __main__/cli/main/entry) in all 3, models in 2 → both pinned; parser (1/3) dropped.
        assert!(bb.contains(&"cli".to_string()), "cli is unanimous: {bb:?}");
        assert!(bb.contains(&"models".to_string()), "models is 2/3: {bb:?}");
        assert!(
            !bb.contains(&"parser".to_string()),
            "parser is only 1/3: {bb:?}"
        );
        assert!(
            !bb.iter().any(|r| r.contains("test")),
            "scaffolding excluded: {bb:?}"
        );
        // <2 drafts → no backbone.
        assert!(consensus_backbone(&[draft(&[("a", "a.py")])]).is_empty());
    }

    #[test]
    fn plan_covers_backbone_requires_every_role() {
        let plan = r#"{"subtasks":[
            {"id":"models","depends_on":[],"files":["pkg/models.py"]},
            {"id":"cli","depends_on":["models"],"files":["pkg/__main__.py"]}
        ]}"#;
        assert!(plan_covers_backbone(plan, &["cli".into(), "models".into()]));
        // A missing role → not covered (the lock was disobeyed).
        assert!(!plan_covers_backbone(
            plan,
            &["cli".into(), "models".into(), "parser".into()]
        ));
        // Invalid JSON → not covered (never adopt an unparseable round-2 plan).
        assert!(!plan_covers_backbone("not json", &["cli".into()]));
    }

    // --- Incremental replan (Phase 1) --------------------------------------------------------------------

    fn spec(id: &str, files: &[&str], deps: &[&str]) -> goose_swarm::TaskSpec {
        goose_swarm::TaskSpec {
            id: id.to_string(),
            description: format!("{id} module"),
            difficulty: goose_swarm::Difficulty::Easy,
            preferred_model: None,
            owned_files: files.iter().map(|s| s.to_string()).collect(),
            deps: deps.iter().map(|s| s.to_string()).collect(),
            subsplit: Vec::new(),
            shard_of: None,
            merger_of: None,
        }
    }

    #[test]
    fn module_votes_tallies_roles_over_the_full_pool() {
        let d1 = vec![
            spec("core", &["core.py"], &[]),
            spec("cli", &["main.py"], &[]),
        ];
        let d2 = vec![
            spec("core", &["core.py"], &[]),
            spec("entry", &["cli.py"], &[]),
        ];
        let d3 = vec![
            spec("core", &["core.py"], &[]),
            spec("parser", &["parser.py"], &[]),
        ];
        let v = module_votes(&[d1, d2, d3]);
        // core unanimous (3/3); cli folded from main/cli/entry (2/3 — d3 has no entry role); parser 1/3.
        assert_eq!(v.get("core"), Some(&(3, 3)));
        assert_eq!(v.get("cli"), Some(&(2, 3)));
        assert_eq!(v.get("parser"), Some(&(1, 3)));
    }

    #[test]
    fn structural_convergence_clears_80_on_diverse_but_convergent() {
        // A,B share a 5-role core; C renames one (e→x) and adds an extra — a genuinely DIVERSE decomposition
        // that the count-spread metric caps at ~74. struct_conv rewards the shared backbone: A=1.0, B=1.0,
        // C = 4/6 = 0.667 → mean 0.889 → 89, which clears the 80 floor the old metric could not reach.
        let core = |extra: &[(&str, &str)]| {
            let mut v = vec![
                spec("a", &["a.py"], &[]),
                spec("b", &["b.py"], &[]),
                spec("c", &["c.py"], &[]),
                spec("d", &["d.py"], &[]),
            ];
            for (id, f) in extra {
                v.push(spec(id, &[f], &[]));
            }
            v
        };
        let a = core(&[("e", "e.py")]);
        let b = core(&[("e", "e.py")]);
        let c = core(&[("x", "x.py"), ("extra", "extra.py")]);
        let (conv, _) = structural_convergence(&[a, b, c]);
        assert_eq!(
            conv, 89,
            "diverse-but-convergent drafts must clear the 80 floor"
        );

        // Fragmented: each draft invents its own modules, nothing shared → won't stop (F3 guarantee).
        let f1 = vec![spec("a", &["a1.py"], &[]), spec("b", &["a2.py"], &[])];
        let f2 = vec![spec("a", &["b1.py"], &[]), spec("b", &["b2.py"], &[])];
        let f3 = vec![spec("a", &["c1.py"], &[]), spec("b", &["c2.py"], &[])];
        let (frag, _) = structural_convergence(&[f1, f2, f3]);
        assert_eq!(frag, 0, "fragmented drafts must NOT fake convergence");
    }

    #[test]
    fn partition_freezes_only_unanimous_and_downward_closed() {
        // core + cli unanimous, eval only 2/3. cli deps on eval, so even though cli's own role is unanimous it
        // CANNOT freeze (downward-closure): its dep eval is dirty. core (root, unanimous) freezes.
        let mk = |eval: bool| {
            let mut s = vec![
                spec("core", &["core.py"], &[]),
                spec("cli", &["main.py"], &["core", "eval"]),
            ];
            if eval {
                s.push(spec("eval", &["eval.py"], &["core"]));
            } else {
                s.push(spec("score", &["score.py"], &["core"])); // a different role, so eval is not unanimous
            }
            s
        };
        let valid = vec![mk(true), mk(true), mk(false)];
        let votes = module_votes(&valid);
        let source = mk(true); // the best draft = one that HAS eval
        let (frozen, dirty) = partition_frozen_dirty(&votes, &source);
        let fids: Vec<&str> = frozen.iter().map(|t| t.id.as_str()).collect();
        assert!(fids.contains(&"core"), "core is unanimous root: {fids:?}");
        assert!(
            !fids.contains(&"cli"),
            "cli deps on dirty eval → not frozen: {fids:?}"
        );
        assert!(
            !fids.contains(&"eval"),
            "eval is only 2/3 → dirty: {fids:?}"
        );
        assert!(dirty.contains(&"eval".to_string()) && dirty.contains(&"cli".to_string()));
        // P0-1 invariant: EVERY frozen task's deps resolve inside the frozen set (never dangles).
        let frozen_ids: std::collections::BTreeSet<&str> =
            frozen.iter().map(|t| t.id.as_str()).collect();
        for t in &frozen {
            for d in &t.deps {
                assert!(
                    frozen_ids.contains(d.as_str()),
                    "frozen `{}` deps on non-frozen `{d}`",
                    t.id
                );
            }
        }
    }

    #[test]
    fn partition_downward_closure_freezes_a_full_chain_when_all_unanimous() {
        // core <- eval <- cli, all unanimous → the whole chain freezes (closure is satisfied at every level).
        let chain = || {
            vec![
                spec("core", &["core.py"], &[]),
                spec("eval", &["eval.py"], &["core"]),
                spec("cli", &["main.py"], &["eval"]),
            ]
        };
        let valid = vec![chain(), chain(), chain()];
        let votes = module_votes(&valid);
        let (frozen, dirty) = partition_frozen_dirty(&votes, &chain());
        assert_eq!(frozen.len(), 3, "all three freeze");
        assert!(dirty.is_empty());
    }

    #[test]
    fn validate_frozen_interfaces_accepts_a_clean_wire_and_rejects_the_r2_breaks() {
        let frozen = vec![spec("core", &["core.py"], &[])];
        // (ok) a dirty module that deps on the frozen id and owns a NEW role.
        let clean = vec![
            spec("cli", &["main.py"], &["core"]),
            spec("integrate-verify", &[], &["core", "cli"]),
        ];
        assert!(validate_frozen_interfaces(&frozen, &clean).is_ok());
        // (ii) dep on a frozen id that does not exist (a changed/renamed frozen id) → unknown dep → reject.
        let bad_dep = vec![spec("cli", &["main.py"], &["kore"])];
        assert!(validate_frozen_interfaces(&frozen, &bad_dep).is_err());
        // (iii) a cycle through a frozen node: give the frozen node a dep on a dirty node, dirty deps back.
        let frozen_cyc = vec![spec("core", &["core.py"], &["cli"])];
        let dirty_cyc = vec![spec("cli", &["main.py"], &["core"])];
        assert!(validate_frozen_interfaces(&frozen_cyc, &dirty_cyc).is_err());
        // (iv) a dirty file whose canonical role collides with a frozen role → reject.
        let role_collide = vec![spec("core2", &["pkg/core.py"], &[])];
        assert!(validate_frozen_interfaces(&frozen, &role_collide).is_err());
        // (b) a dirty task that reuses a frozen id → reject.
        let id_reuse = vec![spec("core", &["other.py"], &[])];
        assert!(validate_frozen_interfaces(&frozen, &id_reuse).is_err());
    }

